INSERT INTO _fields_wd1_plan (site_id, column_name, old_value, new_value, change_key, reason, evidence) VALUES
    ('92313299-3bb1-45c2-aa95-eb147b0269ba'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26b-s007:92313299-3bb1-45c2-aa95-eb147b0269ba:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('92313299-3bb1-45c2-aa95-eb147b0269ba'::uuid, 'period_start', '-1500', NULL, 'fields-wd1-2026-09-26b-s007:92313299-3bb1-45c2-aa95-eb147b0269ba:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-1500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0039)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and Wessex Archaeology describe Little Woodbury only as an Iron Age site/enclosure without any year or century for its foundation, and the excavation report and Historic England entry cannot be read; no two sources date its start, and the stored 1500 BC (Bronze Age) contradicts the Iron Age attribution.", "value_page": null}]'::jsonb),
    ('92313299-3bb1-45c2-aa95-eb147b0269ba'::uuid, 'site_type', 'City/town/settlement', 'Settlement', 'fields-wd1-2026-09-26b-s007:92313299-3bb1-45c2-aa95-eb147b0269ba:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''City/town/settlement'' -> ''Settlement''', '[{"source": "https://en.wikipedia.org/wiki/Little_Woodbury", "url": "https://en.wikipedia.org/wiki/Little_Woodbury", "quote": "A settlement had been identified at the site through aerial archaeology by O.G.S. Crawford almost twenty years previously, when he had seen a circular enclosure as a cropmark.", "outcome": "found"}, {"source": "https://www.wessexarch.co.uk/news/salisbury-sites-34-back-iron-age", "url": "https://www.wessexarch.co.uk/news/salisbury-sites-34-back-iron-age", "quote": "Most significantly nine Iron Age inhumation burials were also found, possibly former residents of Little Woodbury.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0039)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Wessex Archaeology describe Little Woodbury as an enclosed Iron Age settlement (farmstead) with roundhouses, storage pits and residents, not a hillfort and not a town, so Settlement is the most specific type.", "value_page": null}]'::jsonb),
    ('92424ead-7e63-40d3-8796-76f8ef82ae86'::uuid, 'source_url', 'https://www-kulturportali-gov-tr.translate.goog/turkiye/mersin/gezilecekyer/mbriogion-demircili?_x_tr_sl=tr&_x_tr_tl=en&_x_tr_hl=en&_x_tr_pto=sc', 'https://kulturportali.gov.tr/turkiye/mersin/gezilecekyer/mbriogion-demircili', 'fields-wd1-2026-09-26b-s007:92424ead-7e63-40d3-8796-76f8ef82ae86:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://www-kulturportali-gov-tr.translate.goog/turkiye/mersin/gezilecekyer/mbriogion-demircili?_x_tr_sl=tr&_x_tr_tl=en&_x_tr_hl=en&_x_tr_pto=sc'' -> ''https://kulturportali.gov.tr/turkiye/mersin/gezilecekyer/mbriogion-demircili''', '[{"source": "https://kulturportali.gov.tr/turkiye/mersin/gezilecekyer/mbriogion-demircili", "url": "https://kulturportali.gov.tr/turkiye/mersin/gezilecekyer/mbriogion-demircili", "quote": "Demircili Anıt Mezarları - Mersin", "outcome": "found"}, {"source": "https://kulturportali.gov.tr/turkiye/mersin/gezilecekyer/mbriogion-demircili", "url": "https://kulturportali.gov.tr/turkiye/mersin/gezilecekyer/mbriogion-demircili", "quote": "Antik İmbriogion kentinin soylularına ait olan bu anıt mezarların dört tanesi Silifke-Uzuncaburç karayolunun hemen kenarında görülebilmektedir.", "outcome": "found"}, {"source": "https://kureansiklopedi.com/en/detay/demirci-memorial-tomb-ad509", "url": "https://kureansiklopedi.com/en/detay/demirci-memorial-tomb-ad509", "quote": "Demirci Monumental Tombs are Roman-era monumental tombs (2nd century AD) located at the 7th kilometer of the Silifke-Uzuncaburç road in Mersin Province", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0143)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored value is a Google Translate proxy of the Ministry of Culture page ''Demircili Anıt Mezarları''; the page itself, at its own URL, is about exactly these tombs, and the Küre encyclopedia names the same tomb group.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('924cc0ad-a5ee-4200-84b1-8d41fc60d1ff'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26b-s007:924cc0ad-a5ee-4200-84b1-8d41fc60d1ff:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('924cc0ad-a5ee-4200-84b1-8d41fc60d1ff'::uuid, 'period_start', '-1500', NULL, 'fields-wd1-2026-09-26b-s007:924cc0ad-a5ee-4200-84b1-8d41fc60d1ff:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-1500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0040)", "decision": "clear", "status": "MISSING", "reasoning": "The enclosure is unexcavated and dated only by its form: the Exmoor HER files it as an Iron Age hillslope enclosure but notes ''this dating is somewhat tenous'', and Wikipedia says only that it ''may have been'' an Iron Age hill fort; no source attests a start year.", "value_page": null}]'::jsonb),
    ('927cd0d5-2d53-456d-b215-deb419ddf0b9'::uuid, 'period_name', '3000 - 1500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s007:927cd0d5-2d53-456d-b215-deb419ddf0b9:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start -86 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-86) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('927cd0d5-2d53-456d-b215-deb419ddf0b9'::uuid, 'period_start', '-2000', '-86', 'fields-wd1-2026-09-26b-s007:927cd0d5-2d53-456d-b215-deb419ddf0b9:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''-2000'' -> ''-86''', '[{"source": "https://www.attalus.org/docs/seg/s41_448.html", "url": "https://www.attalus.org/docs/seg/s41_448.html", "quote": "Date: 86 B.C.", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Thurion", "url": "https://de.wikipedia.org/wiki/Thurion", "quote": "wo 86 v. Chr. die zweite Schlacht bei Chaironeia stattfand", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0069)", "decision": "replace", "status": "MISSING", "reasoning": "The securely attested monument on the hill is Sulla''s trophy for the battle of Chaironeia, dated 86 BC (SEG 41.448 on Attalus; German Wikipedia dates the battle there to 86 BC); nothing dates any use of the hill to the 2nd millennium BC, so -2000 is replaced by -86.", "value_page": null}]'::jsonb),
    ('927cd0d5-2d53-456d-b215-deb419ddf0b9'::uuid, 'site_type', 'Temple complex', 'Monument', 'fields-wd1-2026-09-26b-s007:927cd0d5-2d53-456d-b215-deb419ddf0b9:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Temple complex'' -> ''Monument''', '[{"source": "https://en.wikipedia.org/wiki/Mount_Thourion", "url": "https://en.wikipedia.org/wiki/Mount_Thourion", "quote": "In gratitude, a monument was erected on the summit with their names carved on it in Greek letters.", "outcome": "found"}, {"source": "https://www.attalus.org/docs/seg/s41_448.html", "url": "https://www.attalus.org/docs/seg/s41_448.html", "quote": "but there is another planted on the crest of Thourion to commemorate the envelopment of the barbarians there, and it indicates in Greek letters that Homoloïchos and Anaxidamos were the heroes of the exploit.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0069)", "decision": "replace", "status": "CONFLICT", "reasoning": "The archaeological remains on Thourion are the commemorative trophy monument of 86 BC on its crest; the temple is only ''likely'' located nearby and no source calls the site a temple complex, so the type becomes Monument.", "value_page": null}]'::jsonb),
    ('9347c4bf-5d34-4773-955d-af52852ce469'::uuid, 'geom', '0101000020E6100000056627C239F251C0C513FEEC55232BC0', 'SRID=4326;POINT(-72.545683 -13.163075)', 'fields-wd1-2026-09-26b-s007:9347c4bf-5d34-4773-955d-af52852ce469:geom', 'fields-wd1-2026-09-26b-s007 (wd1-point): -13.569014936461722, -71.78477529380332 -> -13.163075, -72.545683', '[{"source": "https://en.wikipedia.org/wiki/Intihuatana,_Urubamba", "url": "https://en.wikipedia.org/wiki/Intihuatana,_Urubamba", "quote": "13°09′54″S 72°32′44″W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/874540036", "url": "https://www.openstreetmap.org/node/874540036", "quote": "-13.1630749, -72.5456831", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0110)", "decision": "replace", "status": "MISSING", "reasoning": "Intihuatana, Urubamba is the ritual stone at Machu Picchu (Machupicchu District, Urubamba Province). The English Wikipedia article and the mapped OpenStreetMap node of the stone place it about 0.2 km apart in the Machu Picchu citadel. The stored point lies near Tipon/Patabamba in Quispicanchi, about 90 km away, so it is replaced.", "value_page": null}]'::jsonb),
    ('9347c4bf-5d34-4773-955d-af52852ce469'::uuid, 'lat', '-13.569014936461722', '-13.163075', 'fields-wd1-2026-09-26b-s007:9347c4bf-5d34-4773-955d-af52852ce469:lat', 'fields-wd1-2026-09-26b-s007 (wd1-replace): -13.569014936461722, -71.78477529380332 -> -13.163075, -72.545683', '[{"source": "https://en.wikipedia.org/wiki/Intihuatana,_Urubamba", "url": "https://en.wikipedia.org/wiki/Intihuatana,_Urubamba", "quote": "13°09′54″S 72°32′44″W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/874540036", "url": "https://www.openstreetmap.org/node/874540036", "quote": "-13.1630749, -72.5456831", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0110)", "decision": "replace", "status": "MISSING", "reasoning": "Intihuatana, Urubamba is the ritual stone at Machu Picchu (Machupicchu District, Urubamba Province). The English Wikipedia article and the mapped OpenStreetMap node of the stone place it about 0.2 km apart in the Machu Picchu citadel. The stored point lies near Tipon/Patabamba in Quispicanchi, about 90 km away, so it is replaced.", "value_page": null}]'::jsonb),
    ('9347c4bf-5d34-4773-955d-af52852ce469'::uuid, 'lon', '-71.78477529380332', '-72.545683', 'fields-wd1-2026-09-26b-s007:9347c4bf-5d34-4773-955d-af52852ce469:lon', 'fields-wd1-2026-09-26b-s007 (wd1-replace): -13.569014936461722, -71.78477529380332 -> -13.163075, -72.545683', '[{"source": "https://en.wikipedia.org/wiki/Intihuatana,_Urubamba", "url": "https://en.wikipedia.org/wiki/Intihuatana,_Urubamba", "quote": "13°09′54″S 72°32′44″W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/874540036", "url": "https://www.openstreetmap.org/node/874540036", "quote": "-13.1630749, -72.5456831", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0110)", "decision": "replace", "status": "MISSING", "reasoning": "Intihuatana, Urubamba is the ritual stone at Machu Picchu (Machupicchu District, Urubamba Province). The English Wikipedia article and the mapped OpenStreetMap node of the stone place it about 0.2 km apart in the Machu Picchu citadel. The stored point lies near Tipon/Patabamba in Quispicanchi, about 90 km away, so it is replaced.", "value_page": null}]'::jsonb),
    ('9347c4bf-5d34-4773-955d-af52852ce469'::uuid, 'site_type', 'Megalithic stones', 'Sculptured stone', 'fields-wd1-2026-09-26b-s007:9347c4bf-5d34-4773-955d-af52852ce469:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Megalithic stones'' -> ''Sculptured stone''', '[{"source": "https://illapa.com/attractions/machu-picchu/el-intihuatana-de-machu-picchu/", "url": "https://illapa.com/attractions/machu-picchu/el-intihuatana-de-machu-picchu/", "quote": "Uncover the mystery of Intihuatana, or the solar clock of Machu Picchu a monolithic granite sculpture dating back to the 15th century.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Intihuatana,_Urubamba", "url": "https://en.wikipedia.org/wiki/Intihuatana,_Urubamba", "quote": "The Intihuatana of Machu Picchu was carved directly into the bedrock of the mountain''s summit area.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0110)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe a single ritual stone carved from the granite bedrock, a monolithic sculpture, not a group of megalithic stones. The most specific canonical type is therefore Sculptured stone.", "value_page": null}]'::jsonb),
    ('935c0e07-0e4c-4bf9-a2ea-0113c70a3e3c'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26b-s007:935c0e07-0e4c-4bf9-a2ea-0113c70a3e3c:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('935c0e07-0e4c-4bf9-a2ea-0113c70a3e3c'::uuid, 'period_start', '-4500', NULL, 'fields-wd1-2026-09-26b-s007:935c0e07-0e4c-4bf9-a2ea-0113c70a3e3c:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-4500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0035)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia dates the hills'' archaeology only by period (Bronze Age occupation, Iron Age defences) without a year, century or millennium; the only dated text is the Magog Trust''s period heading ''3000 – 2400 BC Middle Neolithic'' for a possible causewayed enclosure on Little Trees Hill, a single source family. No two independent sources date the start, and the stored -4500 is unsupported.", "value_page": null}]'::jsonb),
    ('935c0e07-0e4c-4bf9-a2ea-0113c70a3e3c'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/History', 'https://en.wikipedia.org/wiki/Gog_Magog_Hills', 'fields-wd1-2026-09-26b-s007:935c0e07-0e4c-4bf9-a2ea-0113c70a3e3c:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/History'' -> ''https://en.wikipedia.org/wiki/Gog_Magog_Hills''', '[{"source": "https://en.wikipedia.org/wiki/Gog_Magog_Hills", "url": "https://en.wikipedia.org/wiki/Gog_Magog_Hills", "quote": "The Gog Magog Hills (known locally as the Gogs) are a range of low chalk hills extending for several miles to the southeast of Cambridge in England.", "outcome": "found"}, {"source": "https://www.magogtrust.org.uk/about/history/", "url": "https://www.magogtrust.org.uk/about/history/", "quote": "The Gog Magog Hills, to the south of Cambridge, are a distinctive part of this largely flat county.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0035)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the generic article ''History''; the site''s own English Wikipedia article (item Q369156) is ''Gog Magog Hills'', and the Magog Trust''s history page names the same hills south of Cambridge.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Gog Magog Hills", "unreadable": false, "wikibase_item": "Q369156"}}]'::jsonb),
    ('93dd77da-64ad-4947-96b3-8ead4d6c98c1'::uuid, 'site_type', 'Necropolis/tombs complex', 'Sanctuary', 'fields-wd1-2026-09-26b-s007:93dd77da-64ad-4947-96b3-8ead4d6c98c1:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Necropolis/tombs complex'' -> ''Sanctuary''', '[{"source": "https://www.swiss-spectator.ch/nederlands-een-keltisch-heiligdom-op-de-mormont/", "url": "https://www.swiss-spectator.ch/nederlands-een-keltisch-heiligdom-op-de-mormont/", "quote": "The Celtic Sanctuary of the Mormont", "outcome": "found"}, {"source": "https://hal.science/hal-02516109v1", "url": "https://hal.science/hal-02516109v1", "quote": "Le sanctuaire celtique du Mormont, Vaud, Suisse", "outcome": "found"}, {"source": "https://sauvonslemormont.ch/historique-du-mormont/les-helvetes/", "url": "https://sauvonslemormont.ch/historique-du-mormont/les-helvetes/", "quote": "Il s’agit d’un lieu de culte Helvète, unique à ce jour en Gaule", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0138)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a field of some 250 deposit pits interpreted as a Helvetian cult place: the Swiss Spectator, the excavators'' paper (Dietrich 2007, HAL) and the local association all call it a Celtic sanctuary or place of worship; the Bibracte museum notes it does not resemble a necropolis, so Necropolis/tombs complex is replaced by Sanctuary.", "value_page": null}]'::jsonb),
    ('93dd77da-64ad-4947-96b3-8ead4d6c98c1'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Mormont', 'https://fr.wikipedia.org/wiki/Mormont_(site_arch%C3%A9ologique)', 'fields-wd1-2026-09-26b-s007:93dd77da-64ad-4947-96b3-8ead4d6c98c1:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Mormont'' -> ''https://fr.wikipedia.org/wiki/Mormont_(site_arch%C3%A9ologique)''', '[{"source": "https://fr.wikipedia.org/wiki/Mormont_(site_arch%C3%A9ologique)", "url": "https://fr.wikipedia.org/wiki/Mormont_(site_arch%C3%A9ologique)", "quote": "Le Mormont est un site archéologique de la fin du second âge du Fer découvert en 2006", "outcome": "found"}, {"source": "https://www.archeodunum.com/Notice_site/eclepens-la-sarraz-351/", "url": "https://www.archeodunum.com/Notice_site/eclepens-la-sarraz-351/", "quote": "Situé près du sommet de la colline de calcaire éponyme, le site du Mormont a fait l’objet de recherches archéologiques programmées entre 2006 et 2016.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0138)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the hill; the French Wikipedia has an article on the archaeological site itself, and the excavator Archeodunum''s site notice names the same site near the hill''s summit.", "value_page": {"lang": "fr", "problem": null, "resolved_title": "Mormont (site archéologique)", "unreadable": false, "wikibase_item": "Q109045459"}}]'::jsonb),
    ('93f7a2e9-2d34-4ac7-bb22-9327d1897648'::uuid, 'period_name', '3000 - 1500 BC', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s007:93f7a2e9-2d34-4ac7-bb22-9327d1897648:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start -1200 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1200) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('93f7a2e9-2d34-4ac7-bb22-9327d1897648'::uuid, 'period_start', '-2000', '-1200', 'fields-wd1-2026-09-26b-s007:93f7a2e9-2d34-4ac7-bb22-9327d1897648:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''-2000'' -> ''-1200''', '[{"source": "https://www.creteunlocked.com/guide/ancient-prinias-rizinia", "url": "https://www.creteunlocked.com/guide/ancient-prinias-rizinia", "quote": "is an important archaeological site that offers a fascinating glimpse into the island''s history, particularly during the Late Minoan IIIC period (around 1200 BC)", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Prinias", "url": "https://en.wikipedia.org/wiki/Prinias", "quote": "Some 680 burials (including ritual burials of dogs and horses) were made in the area between the 13th century and 600 BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0070)", "decision": "replace", "status": "MISSING", "reasoning": "Substantial occupation of the Patela begins at the end of the Bronze Age in Late Minoan IIIC, around 1200 BC, with the necropolis in use from the 13th century BC; the start lies in the 1500-500 BC bucket, not in the stored 3000-1500 BC bucket.", "value_page": null}]'::jsonb),
    ('93f7a2e9-2d34-4ac7-bb22-9327d1897648'::uuid, 'site_type', 'Temple complex', 'Settlement', 'fields-wd1-2026-09-26b-s007:93f7a2e9-2d34-4ac7-bb22-9327d1897648:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Temple complex'' -> ''Settlement''', '[{"source": "https://perseus-aa.github.io/items/aa_3911.html", "url": "https://perseus-aa.github.io/items/aa_3911.html", "quote": "Early Iron Age Cretan refuge settlement in mountains.", "outcome": "found"}, {"source": "https://topostext.org/place/350250URhi", "url": "https://topostext.org/place/350250URhi", "quote": "Minoan settlement with Archaic temples, possibly Rhizenia/Rittenia, Patela hill NW of Prinias, Iraklio, Crete", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Prinias", "url": "https://en.wikipedia.org/wiki/Prinias", "quote": "Prinias developed at a similar time frame with Lato and Polyrrhenia as an Archaic Period settlement", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0070)", "decision": "replace", "status": "CONFLICT", "reasoning": "Perseus, ToposText and Wikipedia all describe the Patela of Prinias as a settlement (possibly ancient Rhizenia) containing two Archaic temples, so Settlement fits better than Temple complex.", "value_page": null}]'::jsonb),
    ('940444fb-1897-4c1f-bdc2-30e967df95c8'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26b-s007:940444fb-1897-4c1f-bdc2-30e967df95c8:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('940444fb-1897-4c1f-bdc2-30e967df95c8'::uuid, 'period_start', '-4000', NULL, 'fields-wd1-2026-09-26b-s007:940444fb-1897-4c1f-bdc2-30e967df95c8:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-4000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0118)", "decision": "clear", "status": "MISSING", "reasoning": "The Portal do Arqueólogo gives only ''Neo-Calcolítico'' and French Wikipedia ''Chalcolithic or early Bronze Age'', with no year, century or millennium; since the rock is a natural outcrop, no source dates a start, so the field is emptied.", "value_page": null}]'::jsonb),
