    ('941ec7f7-645f-4c87-9cc5-f156e7504054'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26b-s007:941ec7f7-645f-4c87-9cc5-f156e7504054:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('941ec7f7-645f-4c87-9cc5-f156e7504054'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26b-s007:941ec7f7-645f-4c87-9cc5-f156e7504054:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0049)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia calls Qohaito a pre-Aksumite settlement without a date (the fifth-millennium BC rock art is in the surrounding area, and the Periplus of the late 1st century AD only attests it already existing); the only year given for its start (around 700 BC) comes from a tour operator, so no two independent sources date the start and the stored 1 AD is emptied.", "value_page": null}]'::jsonb),
    ('944099e9-5dfb-435f-a1a2-0c87eb4660be'::uuid, 'site_type', 'Necropolis/tombs complex', 'Barrow', 'fields-wd1-2026-09-26b-s007:944099e9-5dfb-435f-a1a2-0c87eb4660be:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Necropolis/tombs complex'' -> ''Barrow''', '[{"source": "https://en.wikipedia.org/wiki/Troldkirken", "url": "https://en.wikipedia.org/wiki/Troldkirken", "quote": "Troldkirken is a Stone Age long barrow in the village of Nibe, Denmark.", "outcome": "found"}, {"source": "https://lex.dk/Troldkirken", "url": "https://lex.dk/Troldkirken", "quote": "Den velbevarede langdysse er ca. 50 meter lang og 7 meter bred.", "outcome": "found"}, {"source": "https://www.kulturarv.dk/fundogfortidsminder/Lokalitet/26804/", "url": "https://www.kulturarv.dk/fundogfortidsminder/Lokalitet/26804/", "quote": "Langdyssen Troldkirken går for at være en af Danmarks smukkeste dysser, ikke mindst i kraft af sin høje beliggenhed i landskabet.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0021)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, Lex/Trap Danmark and the national register all describe Troldkirken as a single long barrow (langdysse) with one dolmen chamber, not a necropolis or tomb complex, so Barrow is the fitting type.", "value_page": null}]'::jsonb),
    ('945eea72-1e1d-4156-bd45-d68c250b959b'::uuid, 'site_type', 'Temple complex', 'Religious', 'fields-wd1-2026-09-26b-s007:945eea72-1e1d-4156-bd45-d68c250b959b:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Temple complex'' -> ''Religious''', '[{"source": "https://www.achco.org.af/project/Shewaki", "url": "https://www.achco.org.af/project/Shewaki", "quote": "one of a number of standing structures that formed part of an extensive Buddhist religious complex", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Shewaki", "url": "https://en.wikipedia.org/wiki/Shewaki", "quote": "This pre Islamic Buddhist stupa was built during the Kushan period between the 1st and 3rd centuries CE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a Buddhist stupa within an extensive Buddhist religious complex (ACHCO, Wikipedia); no source calls it a temple, so the religious type fits better than Temple complex.", "value_page": null}]'::jsonb),
    ('945eea72-1e1d-4156-bd45-d68c250b959b'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Shewaki', 'https://www.achco.org.af/project/Shewaki', 'fields-wd1-2026-09-26b-s007:945eea72-1e1d-4156-bd45-d68c250b959b:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Shewaki'' -> ''https://www.achco.org.af/project/Shewaki''', '[{"source": "https://www.achco.org.af/project/Shewaki", "url": "https://www.achco.org.af/project/Shewaki", "quote": "ACHCO has secured funding from ALIPH, the International Alliance for the Protection of Heritage in Conflict Areas, for conservation of a stone masonry stupa at Shewaki, south of Kabul.", "outcome": "found"}, {"source": "https://www.aliph-foundation.org/en/projects/conservation-of-buddhist-era-built-heritage", "url": "https://www.aliph-foundation.org/en/projects/conservation-of-buddhist-era-built-heritage", "quote": "The stupa at Shewaki, located 11 kilometers north of Kabul, dates from the 3rd to 5th centuries CE", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the village of Shewaki; there is no Wikipedia article on the stupa, so the page of ACHCO, the organisation that documented and conserved the stupa, is the page about this site; ALIPH names the same stupa.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('94776f9f-ea10-4b05-87bd-fd30c2cbdf6f'::uuid, 'period_name', '3000 - 1500 BC', NULL, 'fields-wd1-2026-09-26b-s007:94776f9f-ea10-4b05-87bd-fd30c2cbdf6f:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('94776f9f-ea10-4b05-87bd-fd30c2cbdf6f'::uuid, 'period_start', '-3000', NULL, 'fields-wd1-2026-09-26b-s007:94776f9f-ea10-4b05-87bd-fd30c2cbdf6f:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-3000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0021)", "decision": "clear", "status": "MISSING", "reasoning": "Only Wikipedia (English and Danish, one family, citing an information board) dates the mound to 1800-1000 BC; the national register Fund og Fortidsminder (locality 140501-35) dates the round barrow only as ''Oldtid'' (250000 BC - 1066 AD) and it has never been excavated, so no two independent sources date its start.", "value_page": null}]'::jsonb),
    ('94776f9f-ea10-4b05-87bd-fd30c2cbdf6f'::uuid, 'site_type', 'Tomb', 'Barrow', 'fields-wd1-2026-09-26b-s007:94776f9f-ea10-4b05-87bd-fd30c2cbdf6f:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Tomb'' -> ''Barrow''', '[{"source": "https://en.wikipedia.org/wiki/Agri_Bavneh%C3%B8j", "url": "https://en.wikipedia.org/wiki/Agri_Bavneh%C3%B8j", "quote": "Agri Bavnehøj is one of 4 barrow mounds and vista points in National Park Mols Bjerge", "outcome": "found"}, {"source": "https://www.kulturarv.dk/fundogfortidsminder/Lokalitet/45128/", "url": "https://www.kulturarv.dk/fundogfortidsminder/Lokalitet/45128/", "quote": "Rundhøj, Oldtid (dateret 250000 f.Kr. - 1066 e.Kr.)", "outcome": "found"}, {"source": "https://www.kulturarv.dk/fundogfortidsminder/Lokalitet/45128/", "url": "https://www.kulturarv.dk/fundogfortidsminder/Lokalitet/45128/", "quote": "Paa det höieste Punkt af Bakkerne findes en rund Höining, der efter Sigende tidligere var höiere og havde Udseende af en Gravhöi.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0021)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia calls Agri Bavnehøj a burial (barrow) mound and the Danish national register lists the Baunehøi on the summit as a Rundhøj, a round barrow; no source describes a tomb chamber, so Barrow is the most specific fitting type rather than Tomb.", "value_page": null}]'::jsonb),
    ('94b971b9-ea1f-4879-8c25-bf59020f891a'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26b-s007:94b971b9-ea1f-4879-8c25-bf59020f891a:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('94b971b9-ea1f-4879-8c25-bf59020f891a'::uuid, 'period_start', '-4000', NULL, 'fields-wd1-2026-09-26b-s007:94b971b9-ea1f-4879-8c25-bf59020f891a:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-4000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0082)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia''s claim that the plain has been occupied ''from pre-4000 BC'' is uncited (trips.ie repeats it from Wikipedia), and no independent source dates the start of Magh Slécht as a site, so the field is emptied.", "value_page": null}]'::jsonb),
    ('94b971b9-ea1f-4879-8c25-bf59020f891a'::uuid, 'site_type', 'Megalithic structures', 'Sacred site', 'fields-wd1-2026-09-26b-s007:94b971b9-ea1f-4879-8c25-bf59020f891a:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Megalithic structures'' -> ''Sacred site''', '[{"source": "https://templeport.ie/pages/plain-of-blood.html", "url": "https://templeport.ie/pages/plain-of-blood.html", "quote": "The area was the legendary centre of worship of the chief pre-Christian deity of Crom Cruach until St. Patrick and Christianity arrived in the 5th Century.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Magh_Sl%C3%A9cht", "url": "https://en.wikipedia.org/wiki/Magh_Sl%C3%A9cht", "quote": "as it became the nationwide centre of the cult of the", "outcome": "found"}, {"source": "https://folklorefinder.uk/legends/crom-cruach", "url": "https://folklorefinder.uk/legends/crom-cruach", "quote": "Magh Slécht in County Cavan was remembered as the most feared religious site in pre-Christian Ireland", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0082)", "decision": "replace", "status": "CONFLICT", "reasoning": "Kevin White''s study of the ''Ritual Landscape of Magh Slecht'' (Templeport Development Association) and Wikipedia both define Magh Slécht as the plain that was the centre of worship of the pre-Christian deity Crom Cruach, and Folklore Finder calls it the most feared religious site of pre-Christian Ireland; it is a ritual landscape of many monument types rather than a single megalithic structure, so Sacred site is the canonical type that holds it.", "value_page": null}]'::jsonb),
    ('94c02471-3aaa-4736-84e6-a1b52bc7e23b'::uuid, 'geom', '0101000020E6100000B8C3105673AF364036C7F41242B54240', 'SRID=4326;POINT(22.6839 37.3786)', 'fields-wd1-2026-09-26b-s007:94c02471-3aaa-4736-84e6-a1b52bc7e23b:geom', 'fields-wd1-2026-09-26b-s007 (wd1-point): 37.41607891990718, 22.685353640644934 -> 37.3786, 22.6839', '[{"source": "https://topostext.org/place/374227PEua", "url": "https://topostext.org/place/374227PEua", "quote": "Latitude: 37.378600 Longitude: 22.683900", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Eva_(Cynuria)", "url": "https://en.wikipedia.org/wiki/Eva_(Cynuria)", "quote": "37.3786°N 22.6839°E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0064)", "decision": "replace", "status": "CONFLICT", "reasoning": "Ancient Eua is now located at the fortified hilltop of Teichio above Elliniko (identified by an inscribed roof tile; Pritchett, Goester, Shipley, Balandier and Guintrand), which ToposText and English Wikipedia put at 37.3786, 22.6839; the stored point is the Roman villa of Herodes Atticus at Loukou, about 4 km north, so it is replaced.", "value_page": null}]'::jsonb),
