    ('94c02471-3aaa-4736-84e6-a1b52bc7e23b'::uuid, 'period_start', '-1000', NULL, 'fields-wd1-2026-09-26b-s007:94c02471-3aaa-4736-84e6-a1b52bc7e23b:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0064)", "decision": "clear", "status": "MISSING", "reasoning": "The only dated account of the Teichio settlement (Balandier and Guintrand, BCH 2019) says it was occupied from the Geometric period, which is a period and not a year or century, while the other sources date only its 4th-century BC wall; no two independent sources give a dated start, so the field is emptied.", "value_page": null}]'::jsonb),
    ('94c02471-3aaa-4736-84e6-a1b52bc7e23b'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Eva,_Arcadia', 'https://en.wikipedia.org/wiki/Eva_(Cynuria)', 'fields-wd1-2026-09-26b-s007:94c02471-3aaa-4736-84e6-a1b52bc7e23b:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Eva,_Arcadia'' -> ''https://en.wikipedia.org/wiki/Eva_(Cynuria)''', '[{"source": "https://en.wikipedia.org/wiki/Eva_(Cynuria)", "url": "https://en.wikipedia.org/wiki/Eva_(Cynuria)", "quote": "lastly to Eva, which he describes as the largest of the three villages, containing a sanctuary of", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Eva_(Cynuria)", "url": "https://en.wikipedia.org/wiki/Eva_(Cynuria)", "quote": "though he calls it a city of Arcadia", "outcome": "found"}, {"source": "https://topostext.org/place/374227PEua", "url": "https://topostext.org/place/374227PEua", "quote": "Eua, Classical to Roman polis identified by rooftiles with Teichio hilltop at Elleniko in Arkadia Peloponnese", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0064)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL ''Eva,_Arcadia'' is a redirect, merged in 2024 into the article ''Eva (Cynuria)'' on this ancient village of Cynuria (item Q5405223); the article''s own URL replaces the redirect, and ToposText describes the same place.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Eva (Cynuria)", "unreadable": false, "wikibase_item": "Q5405223"}}]'::jsonb),
    ('94fd509a-71e9-4a1e-b235-4eb91b1cacca'::uuid, 'site_type', 'Settlement', 'City', 'fields-wd1-2026-09-26b-s007:94fd509a-71e9-4a1e-b235-4eb91b1cacca:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Settlement'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Mampsis", "url": "https://en.wikipedia.org/wiki/Mampsis", "quote": "is the smallest but best restored ancient city in the Negev Desert", "outcome": "found"}, {"source": "https://www.biblewalks.com/mamshit/", "url": "https://www.biblewalks.com/mamshit/", "quote": "Mamshit (Mampsis) is an ancient Nabatean, Roman and Byzantine city", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0083)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and BibleWalks describe Mampsis as a walled Nabataean, Roman and Byzantine city (one of UNESCO''s Desert Cities of the Negev), so City is the more specific type than Settlement.", "value_page": null}]'::jsonb),
