    ('952e9faf-49f9-4fe9-8cee-f0934167b9df'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s007:952e9faf-49f9-4fe9-8cee-f0934167b9df:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start 1 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('952e9faf-49f9-4fe9-8cee-f0934167b9df'::uuid, 'period_start', '-500', '1', 'fields-wd1-2026-09-26b-s007:952e9faf-49f9-4fe9-8cee-f0934167b9df:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''-500'' -> ''1''', '[{"source": "https://en.wikipedia.org/wiki/Axum", "url": "https://en.wikipedia.org/wiki/Axum", "quote": "Excavations in the Stele Park at the heart of Aksum substantiate ongoing activity in that area since the beginning of the common era. By the 1st century AD, Aksum was described as a", "outcome": "found"}, {"source": "https://www.africanhistoryextra.com/p/the-historic-architecture-of-ethiopia", "url": "https://www.africanhistoryextra.com/p/the-historic-architecture-of-ethiopia", "quote": "and later shifting to the site of Aksum by the late 1st century CE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0049)", "decision": "replace", "status": "MISSING", "reasoning": "At Aksum itself the Stele Park shows activity from the beginning of the common era and the Periplus calls Aksum a metropolis by the 1st century AD; the earlier proto-Aksumite centre (from c. 400 BC, with pre-Aksumite traces) lay on Bieta Giyorgis hill about 1 km north, and the capital shifted to the site of Aksum by the late 1st century CE, so the start is the 1st century AD, 1.", "value_page": null}]'::jsonb),
    ('953e0154-1d30-4502-953d-4de1ff7bda62'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26b-s007:953e0154-1d30-4502-953d-4de1ff7bda62:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('953e0154-1d30-4502-953d-4de1ff7bda62'::uuid, 'period_start', '-4500', NULL, 'fields-wd1-2026-09-26b-s007:953e0154-1d30-4502-953d-4de1ff7bda62:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-4500'' -> None', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0022)", "decision": "clear", "status": "MISSING", "reasoning": "The readable sources give no secure date for this cairn: English Wikipedia (the island article) says the Southcairn dates from approx. 3000 BC while its own category places it in the 4th millennium BC, Historic Environment Scotland says only around 5,000 years old, and the Holm of Papa Westray South cairn has no radiocarbon date quoted anywhere readable, so no two independent sources date the start and the stored -4500 is unattested.", "value_page": null}]'::jsonb),
    ('953e0154-1d30-4502-953d-4de1ff7bda62'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Holm_of_Papa', 'https://www.historicenvironment.scot/visit/all/holm-of-papa-westray-chambered-cairn/', 'fields-wd1-2026-09-26b-s007:953e0154-1d30-4502-953d-4de1ff7bda62:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Holm_of_Papa'' -> ''https://www.historicenvironment.scot/visit/all/holm-of-papa-westray-chambered-cairn/''', '[{"source": "https://www.historicenvironment.scot/visit/all/holm-of-papa-westray-chambered-cairn/", "url": "https://www.historicenvironment.scot/visit/all/holm-of-papa-westray-chambered-cairn/", "quote": "The Holm of Papa Westray chambered cairn is a large and eccentric monument.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=1359378658", "url": "https://www.megalithic.co.uk/article.php?sid=1359378658", "quote": "Site Name: Holm of Papa Westray South Alternative Name: Diss o''the Holm", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0123)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the island Holm of Papa; the cairn has no Wikipedia article in any language (Wikidata item without sitelinks), so the Historic Environment Scotland page of the cairn, which it manages as a property in care, replaces it.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
