    ('9599cc2a-23cc-44e9-9e5c-420b3392ca10'::uuid, 'period_name', '1 - 500 AD', '1000 - 1500 AD', 'fields-wd1-2026-09-26b-s007:9599cc2a-23cc-44e9-9e5c-420b3392ca10:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start 1320 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1320) = ''1000 - 1500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('9599cc2a-23cc-44e9-9e5c-420b3392ca10'::uuid, 'period_start', '1', '1320', 'fields-wd1-2026-09-26b-s007:9599cc2a-23cc-44e9-9e5c-420b3392ca10:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''1'' -> ''1320''', '[{"source": "https://visitgilgitbaltistan.gov.pk/tour/id/76", "url": "https://visitgilgitbaltistan.gov.pk/tour/id/76", "quote": "This minar, approximately 700 years old, was built by the Taj-ud-Din Mughal a ruler from Badakhshan after conquering Gilgit in the 1320s.", "outcome": "found"}, {"source": "https://www.travelershorizon.pk/victory-monument-of-taj-mughal/", "url": "https://www.travelershorizon.pk/victory-monument-of-taj-mughal/", "quote": "The monument was named after Taj-ud-Din Mughal, an Ismaili ruler from Badakhshan, who came to Gilgit -Baltistan during the 13th century AD. The monument was built by his soldiers to celebrate his victory.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0104)", "decision": "replace", "status": "MISSING", "reasoning": "The Gilgit-Baltistan tourism department dates the tower''s construction by Taj-ud-Din Mughal to the 1320s and Traveler''s Horizon to his arrival in the 13th century AD; both place the start in 1000 - 1500 AD, not in the stored 1 - 500 AD bucket, and no source dates an earlier stupa phase.", "value_page": null}]'::jsonb),
    ('9599cc2a-23cc-44e9-9e5c-420b3392ca10'::uuid, 'site_type', 'Temple complex', 'Minaret/tower', 'fields-wd1-2026-09-26b-s007:9599cc2a-23cc-44e9-9e5c-420b3392ca10:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Temple complex'' -> ''Minaret/tower''', '[{"source": "https://www.travelershorizon.pk/victory-monument-of-taj-mughal/", "url": "https://www.travelershorizon.pk/victory-monument-of-taj-mughal/", "quote": "The tower is round in shape yet gradually losing its composition and may come down to disappear at some point.", "outcome": "found"}, {"source": "https://visitgilgitbaltistan.gov.pk/tour/id/76", "url": "https://visitgilgitbaltistan.gov.pk/tour/id/76", "quote": "Its height is approximately twenty to twenty-five feet. It is located on the south mountain of Khomar and Jutial, the base of the hill is about one kilometer from Gilgit city.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0104)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the Mughal Minar as a single round stone tower (minar) about 20-25 feet high on a mountain ridge, not a temple complex; Wikidata also classes it as a tower.", "value_page": null}]'::jsonb),
    ('95c9c8c1-e8ed-43b3-a87b-b79715442dbd'::uuid, 'geom', '0101000020E6100000C2557924ED4956C041E0F8B5DB413140', 'SRID=4326;POINT(-89.145167 17.255082)', 'fields-wd1-2026-09-26b-s007:95c9c8c1-e8ed-43b3-a87b-b79715442dbd:geom', 'fields-wd1-2026-09-26b-s007 (wd1-point): 17.25725877119135, -89.15509902810211 -> 17.255082, -89.145167', '[{"source": "https://www.megalithic.co.uk/article.php?sid=29530", "url": "https://www.megalithic.co.uk/article.php?sid=29530", "quote": "Latitude: 17.255082N Longitude: 89.145167W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/6021038933", "url": "https://www.openstreetmap.org/node/6021038933", "quote": "Location: 17.2538690, -89.1454722", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0011)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Megalithic Portal and the OpenStreetMap node for El Pilar independently place the site at the Belize-side monumental core (about 17.254-17.255 N, 89.145 W), where MARC says the surveys and excavations of the Belizean park concentrate; the stored point sits about 1.08 km further west on the Guatemalan side of the border (Wikipedia''s point, which itself differs by 1.1 km from Wikidata''s), so the point moves to the core.", "value_page": null}]'::jsonb),
    ('95c9c8c1-e8ed-43b3-a87b-b79715442dbd'::uuid, 'lat', '17.25725877119135', '17.255082', 'fields-wd1-2026-09-26b-s007:95c9c8c1-e8ed-43b3-a87b-b79715442dbd:lat', 'fields-wd1-2026-09-26b-s007 (wd1-replace): 17.25725877119135, -89.15509902810211 -> 17.255082, -89.145167', '[{"source": "https://www.megalithic.co.uk/article.php?sid=29530", "url": "https://www.megalithic.co.uk/article.php?sid=29530", "quote": "Latitude: 17.255082N Longitude: 89.145167W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/6021038933", "url": "https://www.openstreetmap.org/node/6021038933", "quote": "Location: 17.2538690, -89.1454722", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0011)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Megalithic Portal and the OpenStreetMap node for El Pilar independently place the site at the Belize-side monumental core (about 17.254-17.255 N, 89.145 W), where MARC says the surveys and excavations of the Belizean park concentrate; the stored point sits about 1.08 km further west on the Guatemalan side of the border (Wikipedia''s point, which itself differs by 1.1 km from Wikidata''s), so the point moves to the core.", "value_page": null}]'::jsonb),
    ('95c9c8c1-e8ed-43b3-a87b-b79715442dbd'::uuid, 'lon', '-89.15509902810211', '-89.145167', 'fields-wd1-2026-09-26b-s007:95c9c8c1-e8ed-43b3-a87b-b79715442dbd:lon', 'fields-wd1-2026-09-26b-s007 (wd1-replace): 17.25725877119135, -89.15509902810211 -> 17.255082, -89.145167', '[{"source": "https://www.megalithic.co.uk/article.php?sid=29530", "url": "https://www.megalithic.co.uk/article.php?sid=29530", "quote": "Latitude: 17.255082N Longitude: 89.145167W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/6021038933", "url": "https://www.openstreetmap.org/node/6021038933", "quote": "Location: 17.2538690, -89.1454722", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0011)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Megalithic Portal and the OpenStreetMap node for El Pilar independently place the site at the Belize-side monumental core (about 17.254-17.255 N, 89.145 W), where MARC says the surveys and excavations of the Belizean park concentrate; the stored point sits about 1.08 km further west on the Guatemalan side of the border (Wikipedia''s point, which itself differs by 1.1 km from Wikidata''s), so the point moves to the core.", "value_page": null}]'::jsonb),
    ('95eeacda-306b-492d-9508-6321bbf2c203'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd1-2026-09-26b-s007:95eeacda-306b-492d-9508-6321bbf2c203:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('95eeacda-306b-492d-9508-6321bbf2c203'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26b-s007:95eeacda-306b-492d-9508-6321bbf2c203:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0009)", "decision": "clear", "status": "MISSING", "reasoning": "The readable sources do not agree on when Stymphalos begins: the BSA lecture notice says finds date from the Middle Palaeolithic through the Bronze Age, a Greek tourism page dates Mycenaean habitation to the 16th century BC while visitsikyon.gr says the 13th and 14th centuries BC and dates the city''s establishment only to the Archaic period, Wikipedia and the AIA describe the excavated city as refounded or planned in the 4th century BC. No two independent sources give the same dated start, and none supports the stored -500, so the field is emptied.", "value_page": null}]'::jsonb),
    ('95eeacda-306b-492d-9508-6321bbf2c203'::uuid, 'site_type', 'Temple complex', 'City', 'fields-wd1-2026-09-26b-s007:95eeacda-306b-492d-9508-6321bbf2c203:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Temple complex'' -> ''City''', '[{"source": "https://visitsikyon.gr/en/attractions/archaeological-site-stymphalia", "url": "https://visitsikyon.gr/en/attractions/archaeological-site-stymphalia", "quote": "lie the ruins of the ancient city of Stymphalos", "outcome": "found"}, {"source": "https://www.archaeological.org/event/stymphalos-a-planned-city-of-ancient-arcadia-lecture-by-hector-williams-u-british-columbia/", "url": "https://www.archaeological.org/event/stymphalos-a-planned-city-of-ancient-arcadia-lecture-by-hector-williams-u-british-columbia/", "quote": "Excavations at ancient Stymphalos, a small Arcadian late classical city set 2000 feet up in the mountains of the northern Peloponnese", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0009)", "decision": "replace", "status": "CONFLICT", "reasoning": "The municipality of Sikyon''s site page and the Archaeological Institute of America lecture notice on the University of British Columbia excavations both describe Stymphalos, on the north shore of Lake Stymphalia, as an ancient city (a small Arcadian city with houses, fortification walls, theatre and sanctuaries); the stored ''Temple complex'' covers only one part of it, so the type is City.", "value_page": null}]'::jsonb),
    ('9635c4e8-6385-4bdb-a952-c9f53a4b2403'::uuid, 'site_type', 'Castle/palace', 'Palace', 'fields-wd1-2026-09-26b-s007:9635c4e8-6385-4bdb-a952-c9f53a4b2403:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Castle/palace'' -> ''Palace''', '[{"source": "https://en.wikipedia.org/wiki/Gamzigrad", "url": "https://en.wikipedia.org/wiki/Gamzigrad", "quote": "Systematic archaeological excavations conducted since 1953 revealed that the site was, in fact, an Imperial palace.", "outcome": "found"}, {"source": "https://culturalheritageonline.com/places/gamzigrad-romuliana-palace-of-galerius/", "url": "https://culturalheritageonline.com/places/gamzigrad-romuliana-palace-of-galerius/", "quote": "Rising from the plains of eastern Serbia, Felix Romuliana is one of the best-preserved late Roman imperial complexes in the Balkans — a walled palace, twin temples, ceremonial arch, and deification tumuli built by the emperor Galerius", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0125)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the site as Galerius''s imperial palace; nothing calls it a castle, so the more specific canonical type Palace replaces the combined Castle/palace.", "value_page": null}]'::jsonb),
    ('9705b676-7ba1-465f-aebd-a21f346de5a1'::uuid, 'period_name', '3000 - 1500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s007:9705b676-7ba1-465f-aebd-a21f346de5a1:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start -500 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-500) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('9705b676-7ba1-465f-aebd-a21f346de5a1'::uuid, 'period_start', '-2000', '-500', 'fields-wd1-2026-09-26b-s007:9705b676-7ba1-465f-aebd-a21f346de5a1:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''-2000'' -> ''-500''', '[{"source": "https://www.anglesey-history.co.uk/places/prehistoric-monuments/ty-mawr-hut-circles/", "url": "https://www.anglesey-history.co.uk/places/prehistoric-monuments/ty-mawr-hut-circles/", "quote": "more recent evidence suggest that huts were occupied as far back as during the Iron Age, about 500 BC", "outcome": "found"}, {"source": "https://coflein.gov.uk/en/sites/308078", "url": "https://coflein.gov.uk/en/sites/308078", "quote": "radio-carbon determinations point to occupation from the middle years of the first millennium BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0154)", "decision": "replace", "status": "MISSING", "reasoning": "Coflein (RCAHMW, radiocarbon) puts the occupation of the Holyhead Mountain hut settlement from the middle years of the first millennium BC and Anglesey History dates the huts to the Iron Age, about 500 BC (Cadw''s scheduling text likewise dates the settlement to the late first millennium BC, with only stray earlier activity from the late third millennium BC), so the start of the hut settlement lies in the 500 BC - 1 AD bucket, not the stored 3000 - 1500 BC.", "value_page": null}]'::jsonb),
    ('9705b676-7ba1-465f-aebd-a21f346de5a1'::uuid, 'site_type', 'Residence/villa/farmhouse', 'Settlement', 'fields-wd1-2026-09-26b-s007:9705b676-7ba1-465f-aebd-a21f346de5a1:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Residence/villa/farmhouse'' -> ''Settlement''', '[{"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2512", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2512", "quote": "The monument consists of an area of later prehistoric settlement features, generally stone founded roundhouses, occupying a natural shelf or terrace below the south-eastern flank of Holyhead Mountain.", "outcome": "found"}, {"source": "https://coflein.gov.uk/en/sites/308078", "url": "https://coflein.gov.uk/en/sites/308078", "quote": "an area of later Prehistoric settlement features, generally stone founded roundhouses, occupying a natural shelf or terrace below the south-eastern flank of Holyhead Mountain.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0026)", "decision": "replace", "status": "MISSING", "reasoning": "Cadw (scheduled monument AN016, Holyhead Mountain Prehistoric Village, Trearddur, Anglesey) and the RCAHMW Coflein record for the Ty Mawr Hut Group / Cytiau''r Gwyddelod (NPRN 308078, type of site SETTLEMENT) both describe the hut circles as an area of prehistoric settlement features made of stone-founded roundhouses, so the site is a prehistoric settlement rather than a single residence, villa or farmhouse.", "value_page": null}]'::jsonb),
    ('9711aeef-a3b2-45ad-8f2c-6c8f033eb9ec'::uuid, 'site_type', 'City/town/settlement', 'Monument', 'fields-wd1-2026-09-26b-s007:9711aeef-a3b2-45ad-8f2c-6c8f033eb9ec:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''City/town/settlement'' -> ''Monument''', '[{"source": "https://it.wikipedia.org/wiki/Macellum_di_Pozzuoli", "url": "https://it.wikipedia.org/wiki/Macellum_di_Pozzuoli", "quote": "Per il duplice interesse che esso ha, archeologico e scientifico, è uno dei più noti monumenti di tutto il mondo antico.", "outcome": "found"}, {"source": "https://www.opencampania.it/it/poi/Macellum-di-Pozzuoli/", "url": "https://www.opencampania.it/it/poi/Macellum-di-Pozzuoli/", "quote": "si erge uno dei monumenti più noti e rappresentativi di tutto il mondo antico, celebre sia dal punto di vista archeologico che da quello scientifico: il Macellum di Pozzuoli, detto anche Tempio di Serapide", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0085)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a single Roman public building, the food market of Puteoli, not a settlement; with no market type in the canonical list, Wikipedia and Open Campania both describe it as one of the best-known monuments of the ancient world, so Monument replaces City/town/settlement.", "value_page": null}]'::jsonb),
    ('972ded7c-665e-4ca6-98cc-af4dff9ac8f3'::uuid, 'period_name', '1 - 500 AD', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s007:972ded7c-665e-4ca6-98cc-af4dff9ac8f3:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start -350 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-350) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('972ded7c-665e-4ca6-98cc-af4dff9ac8f3'::uuid, 'period_start', '1', '-350', 'fields-wd1-2026-09-26b-s007:972ded7c-665e-4ca6-98cc-af4dff9ac8f3:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''1'' -> ''-350''', '[{"source": "https://www.whitman.edu/theatre/theatretour/priene/commentary/priene.commentary.htm", "url": "https://www.whitman.edu/theatre/theatretour/priene/commentary/priene.commentary.htm", "quote": "The city of Priene dates from 350 BC, and the theatre was constructed at the site soon after (ca. 332-330 BC).", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Priene", "url": "https://en.wikipedia.org/wiki/Priene", "quote": "The city visible on the slopes and escarpment of Mycale was constructed according to plan entirely during the 4th century BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0147)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ruins at Güllübahçe are the planned city refounded in the 4th century BC (Whitman''s Ancient Theatre Archive: 350 BC; Wikipedia: 4th century BCE); the c. 1000 BC foundation belongs to the original Priene, whose site has never been found. The start lies in 500 BC - 1 AD, not in 1 - 500 AD.", "value_page": null}]'::jsonb),
    ('972ded7c-665e-4ca6-98cc-af4dff9ac8f3'::uuid, 'site_type', 'Temple complex', 'City', 'fields-wd1-2026-09-26b-s007:972ded7c-665e-4ca6-98cc-af4dff9ac8f3:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Temple complex'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Priene", "url": "https://en.wikipedia.org/wiki/Priene", "quote": "was an ancient Greek city of Ionia", "outcome": "found"}, {"source": "https://www.whitman.edu/theatre/theatretour/priene/priene.htm", "url": "https://www.whitman.edu/theatre/theatretour/priene/priene.htm", "quote": "The city of Priene is located on the northern edge of the Meander River plain approximately thirty kilometers from the present day Turkish city of Kusadasi.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0147)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Whitman''s Ancient Theatre Archive both describe Priene as a city; the ruins hold temples among many civic buildings, so the site is a city, not a temple complex.", "value_page": null}]'::jsonb),
    ('9760e579-1005-4b8f-bf08-b9be81a716da'::uuid, 'site_type', 'Mound/tumulus', 'Cemetery', 'fields-wd1-2026-09-26b-s007:9760e579-1005-4b8f-bf08-b9be81a716da:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Mound/tumulus'' -> ''Cemetery''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=11134", "url": "https://www.megalithic.co.uk/article.php?sid=11134", "quote": "Type: Barrow Cemetery", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Oldendorfer_Totenstatt", "url": "https://de.wikipedia.org/wiki/Oldendorfer_Totenstatt", "quote": "Die Oldendorfer Totenstatt ist ein Ensemble von sechs Grabhügeln und Großsteingräbern in Oldendorf", "outcome": "found"}, {"source": "https://maps.adac.de/poi/oldendorfer-totenstatt-oldendorf", "url": "https://maps.adac.de/poi/oldendorfer-totenstatt-oldendorf", "quote": "Bei Oldendorf befindet sich die Oldendorfer Totenstatt, die seit der Jungsteinzeit um 3700 v. Chr. als Friedhof diente.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0059)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is not a single mound or dolmen but an ensemble of six graves (three long barrows, a passage grave in a round mound, two Bronze Age round barrows) used as a burial ground; the Megalithic Portal types it as a barrow cemetery and ADAC calls it a Friedhof, so Cemetery is the type that holds the whole site.", "value_page": null}]'::jsonb),
    ('9794f4c4-12b0-47a7-b454-a6611d441795'::uuid, 'geom', '0101000020E610000015E8C807CEAC5F40FCDA97797BB74140', 'SRID=4326;POINT(126.6523 35.4418)', 'fields-wd1-2026-09-26b-s007:9794f4c4-12b0-47a7-b454-a6611d441795:geom', 'fields-wd1-2026-09-26b-s007 (wd1-point): 35.433455657146595, 126.70007509822638 -> 35.4418, 126.6523', '[{"source": "https://www.wikidata.org/wiki/Q66197761", "url": "https://www.wikidata.org/wiki/Q66197761", "quote": "35°26''30.480\"N, 126°39''8.280\"E", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=51608", "url": "https://www.megalithic.co.uk/article.php?sid=51608", "quote": "Latitude: 35.441670N  Longitude: 126.652180E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0127)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored point (35.4335, 126.7001) is Gochang-eup, the county town, 4.4 km east of the dolmens. The serial World Heritage site''s largest and most varied group is the Gochang Dolmen Site (component 977-001) at Jungnim-ri/Dosan-ri. Wikidata gives that component at 35.4418, 126.6523, and the Megalithic Portal gives it at 35.44167, 126.65218, 0.01 km apart. UNESCO''s single reference point, 34.96667, 126.92917, lies in the Hwasun component, 55 km away.", "value_page": null}]'::jsonb),
