    ('97bdea94-4c2b-4508-83c3-777aaa16de29'::uuid, 'period_name', '500 BC - 1 AD', '1000 - 1500 AD', 'fields-wd1-2026-09-26b-s007:97bdea94-4c2b-4508-83c3-777aaa16de29:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start 1181 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1181) = ''1000 - 1500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('97bdea94-4c2b-4508-83c3-777aaa16de29'::uuid, 'period_start', '-500', '1181', 'fields-wd1-2026-09-26b-s007:97bdea94-4c2b-4508-83c3-777aaa16de29:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''-500'' -> ''1181''', '[{"source": "https://ancientworldatlas.com/sites/lalibela", "url": "https://ancientworldatlas.com/sites/lalibela", "quote": "Mainstream: c. 1181–1221 AD (reign of Gebre Mesqel Lalibela)", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Rock-Hewn_Churches,_Lalibela", "url": "https://en.wikipedia.org/wiki/Rock-Hewn_Churches,_Lalibela", "quote": "named after the late-12th and early-13th century King Gebre Meskel Lalibela of the Zagwe dynasty, who commissioned the massive building project of 11 rock-hewn churches", "outcome": "found"}, {"source": "https://africanworldheritagesites.org/cultural-places/ancient-ethiopia/lalibela.html", "url": "https://africanworldheritagesites.org/cultural-places/ancient-ethiopia/lalibela.html", "quote": "but these churches are attributed to the 13th-century King Lalibela", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0050)", "decision": "replace", "status": "MISSING", "reasoning": "The churches are attributed to King Gebre Meskel Lalibela (r. c. 1181-1221), late 12th to early 13th century; earlier carving phases (Phillipson''s 7th-8th century, the French mission''s 10th-11th century occupation) are proposals, not securely attested. The stored -500 is far off; the start belongs in the 1000 - 1500 AD bucket.", "value_page": null}]'::jsonb),
    ('97bdea94-4c2b-4508-83c3-777aaa16de29'::uuid, 'site_type', 'Temple complex', 'Church', 'fields-wd1-2026-09-26b-s007:97bdea94-4c2b-4508-83c3-777aaa16de29:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Temple complex'' -> ''Church''', '[{"source": "https://en.wikipedia.org/wiki/Rock-Hewn_Churches,_Lalibela", "url": "https://en.wikipedia.org/wiki/Rock-Hewn_Churches,_Lalibela", "quote": "The eleven Rock-hewn Churches of Lalibela are monolithic churches located in the western Ethiopian Highlands near the town of Lalibela", "outcome": "found"}, {"source": "https://africanworldheritagesites.org/cultural-places/ancient-ethiopia/lalibela.html", "url": "https://africanworldheritagesites.org/cultural-places/ancient-ethiopia/lalibela.html", "quote": "There are 11 churches, each one carved out of solid rock", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0050)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the site as a group of eleven rock-hewn Christian churches; Church is the most specific canonical type, while Temple complex does not describe Christian churches.", "value_page": null}]'::jsonb),
    ('97bdea94-4c2b-4508-83c3-777aaa16de29'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Lalibela', 'https://en.wikipedia.org/wiki/Rock-Hewn_Churches,_Lalibela', 'fields-wd1-2026-09-26b-s007:97bdea94-4c2b-4508-83c3-777aaa16de29:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Lalibela'' -> ''https://en.wikipedia.org/wiki/Rock-Hewn_Churches,_Lalibela''', '[{"source": "https://en.wikipedia.org/wiki/Rock-Hewn_Churches,_Lalibela", "url": "https://en.wikipedia.org/wiki/Rock-Hewn_Churches,_Lalibela", "quote": "The eleven Rock-hewn Churches of Lalibela are monolithic churches located in the western Ethiopian Highlands near the town of Lalibela", "outcome": "found"}, {"source": "https://africanworldheritagesites.org/cultural-places/ancient-ethiopia/lalibela.html", "url": "https://africanworldheritagesites.org/cultural-places/ancient-ethiopia/lalibela.html", "quote": "The rock-hewn churches of Lalibela are located in a remote and mountainous area of northern Ethiopia, about 150 km east of Lake Tana.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0050)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the town of Lalibela; the English Wikipedia article Rock-Hewn Churches, Lalibela is about the site itself, the World Heritage complex of eleven churches.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Rock-Hewn Churches, Lalibela", "unreadable": false, "wikibase_item": "Q642979"}}]'::jsonb),
    ('9803a37d-458e-445c-9fec-8d94a0f89f1c'::uuid, 'site_type', 'Necropolis/tombs complex', 'City', 'fields-wd1-2026-09-26b-s007:9803a37d-458e-445c-9fec-8d94a0f89f1c:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Necropolis/tombs complex'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Parium", "url": "https://en.wikipedia.org/wiki/Parium", "quote": "was a Greek city of Adrasteia in Mysia", "outcome": "found"}, {"source": "https://turkisharchaeonews.net/site/parion-kemer", "url": "https://turkisharchaeonews.net/site/parion-kemer", "quote": "Parion, also called Parium, was a Greek city located on the border of historical lands of Troad and Mysia.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0146)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Turkish Archaeological News describe Parion as a Greek city (a harbour city with theatre, odeion and baths); its necropolis is one part of the city, so City replaces Necropolis/tombs complex.", "value_page": null}]'::jsonb),
    ('98c794a6-57b5-4783-b38d-3693bb60b91b'::uuid, 'site_type', 'Megalithic structures', 'Monument', 'fields-wd1-2026-09-26b-s007:98c794a6-57b5-4783-b38d-3693bb60b91b:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Megalithic structures'' -> ''Monument''', '[{"source": "http://odysseus.culture.gr/h/3/eh352.jsp?obj_id=4925", "url": "http://odysseus.culture.gr/h/3/eh352.jsp?obj_id=4925", "quote": "The Treasury of the Athenians was the only Delphic monument that still preserved much of its ancient fabric in the early twentieth century", "outcome": "found"}, {"source": "https://journals.library.unt.edu/index.php/undergrad/article/view/399", "url": "https://journals.library.unt.edu/index.php/undergrad/article/view/399", "quote": "The Athenian Treasury at Delphi, constructed after the Battle of Marathon in 490 BCE, is understood as a votive offering to Apollo commemorating the Athenians'' victory over the Persians. This paper argues instead that the treasury functioned more as an assertion of Athenian political and cultural superiority within the Panhellenic landscape of the sanctuary. With the placement, materials, inscriptions, and iconographic program of the thirty metopes, this paper reinterprets the monument as an exercise in conspicuous consumption and political promotion rather than collective piety.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0062)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Greek Ministry of Culture calls the Treasury of the Athenians a Delphic monument, and a University of North Texas study describes it as a votive offering to Apollo within the sanctuary and reinterprets ''the monument'' politically; it is a small votive treasury building, not a megalithic structure, so Monument is the fitting type.", "value_page": null}]'::jsonb),
    ('98e72c8a-806c-4a84-bdb6-0ba92ea20010'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26b-s007:98e72c8a-806c-4a84-bdb6-0ba92ea20010:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('98e72c8a-806c-4a84-bdb6-0ba92ea20010'::uuid, 'period_start', '-1000', NULL, 'fields-wd1-2026-09-26b-s007:98e72c8a-806c-4a84-bdb6-0ba92ea20010:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0032)", "decision": "clear", "status": "MISSING", "reasoning": "Only the National Trust''s HER record gives a date, and that is the generic Iron Age span (800 BC to 42 AD) of its monument class; the other sources say only ''Iron Age'' or ''2000 year old''. No two independent sources date the hillfort''s construction, so the field is emptied.", "value_page": null}]'::jsonb),
    ('98e72c8a-806c-4a84-bdb6-0ba92ea20010'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26b-s007:98e72c8a-806c-4a84-bdb6-0ba92ea20010:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://en.wikipedia.org/wiki/Cley_Hill", "url": "https://en.wikipedia.org/wiki/Cley_Hill", "quote": "Archaeological features include a large univallate Iron Age hill fort, two bowl barrows and medieval strip lynchets.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=8364", "url": "https://www.megalithic.co.uk/article.php?sid=8364", "quote": "Site Name: Cley Hill Country: England County: Wiltshire Type: Hillfort", "outcome": "found"}, {"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA138235", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA138235", "quote": "The univallate hill-fort occupies the entire summit of this downland hill.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0005)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, the Megalithic Portal and the National Trust heritage record (three independent families) all describe Cley Hill near Warminster, Wiltshire, as a univallate Iron Age hill fort; a hill fort is a fort, not a fortress or citadel, so the canonical type is Fort.", "value_page": null}]'::jsonb),
    ('98e72c8a-806c-4a84-bdb6-0ba92ea20010'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Cley_Hill', 'https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA138235', 'fields-wd1-2026-09-26b-s007:98e72c8a-806c-4a84-bdb6-0ba92ea20010:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Cley_Hill'' -> ''https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA138235''', '[{"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA138235", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA138235", "quote": "Iron Age Hillfort, Cley Hill", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=8364", "url": "https://www.megalithic.co.uk/article.php?sid=8364", "quote": "Site Name: Cley Hill", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0032)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the hill (its SSSI grassland, geology and legends) rather than the hillfort, which has no article of its own; the Historic England entry refuses automated requests. The National Trust''s heritage record for the Iron Age hillfort on Cley Hill is a readable register entry about this very site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
