    ('99328522-518c-40cd-94a1-b541906c3f00'::uuid, 'period_start', '1400', NULL, 'fields-wd1-2026-09-26b-s007:99328522-518c-40cd-94a1-b541906c3f00:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''1400'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0113)", "decision": "clear", "status": "MISSING", "reasoning": "No source dates the site itself: the MINCETUR inventory text only recounts the regional sequence (Huari 7th-12th century, Chanka state in the 13th century, then the Inca) without dating Puntay Urqu, so the stored 1400 has no two sources.", "value_page": null}]'::jsonb),
    ('99328522-518c-40cd-94a1-b541906c3f00'::uuid, 'site_type', 'City/town/settlement', 'Archaeological site', 'fields-wd1-2026-09-26b-s007:99328522-518c-40cd-94a1-b541906c3f00:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''City/town/settlement'' -> ''Archaeological site''', '[{"source": "https://en.wikipedia.org/wiki/Puntay_Urqu", "url": "https://en.wikipedia.org/wiki/Puntay_Urqu", "quote": "is a mountain and an archaeological site in Peru located in the", "outcome": "found"}, {"source": "https://www.turismoperuano.com/monumento-arqueologico-de-puntay-urqu-ayacucho", "url": "https://www.turismoperuano.com/monumento-arqueologico-de-puntay-urqu-ayacucho", "quote": "el sitio arqueológico se ubica en el anexo de Rayme Alto", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0113)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the MINCETUR inventory agree only that Puntay Urqu is an archaeological site on a mountain summit near Rayme Alto; the inventory describes defensive circular and subterranean dwellings (and classes it under ''Templos'') but no English source calls it a town or settlement, so the generic type is the one that holds.", "value_page": null}]'::jsonb),
    ('99341592-6e5c-4676-8037-cf8b0b763128'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s007:99341592-6e5c-4676-8037-cf8b0b763128:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start -300 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-300) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('99341592-6e5c-4676-8037-cf8b0b763128'::uuid, 'period_start', '-1500', '-300', 'fields-wd1-2026-09-26b-s007:99341592-6e5c-4676-8037-cf8b0b763128:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''-1500'' -> ''-300''', '[{"source": "https://www.secretplacesatlas.com/napoli-sotterranea-underground-naples/", "url": "https://www.secretplacesatlas.com/napoli-sotterranea-underground-naples/", "quote": "The story begins in the 3rd century BC, when the ancient Greeks first excavated volcanic tuff stone from underground quarries.", "outcome": "found"}, {"source": "https://www.napolisotterranea.org/en/", "url": "https://www.napolisotterranea.org/en/", "quote": "the one that began in the third century BC, where the Greeks opened the first underground quarries to obtain the tuff blocks necessary to build the walls and temples of their Neapolis", "outcome": "found"}, {"source": "https://sotterranea.napoli.it/en", "url": "https://sotterranea.napoli.it/en", "quote": "The history of Naples Underground begins in the 4th century BC, when the Greeks began quarrying tuff to build the walls of Neapolis.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0086)", "decision": "replace", "status": "MISSING", "reasoning": "The official Napoli Sotterranea site and Secret Places Atlas date the first underground tuff quarries of the Greeks, the start of the subterranean network, to the 3rd century BC (another guide says the 4th); either way the start lies in the 500 BC - 1 AD bucket, not the stored 1500 - 500 BC, so the value becomes -300.", "value_page": null}]'::jsonb),
