    ('9983bdce-9f35-47a3-a570-4021cfa41b97'::uuid, 'period_start', '-3000', '-1050', 'fields-wd1-2026-09-26b-s007:9983bdce-9f35-47a3-a570-4021cfa41b97:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''-3000'' -> ''-1050''', '[{"source": "https://en.wikipedia.org/wiki/Kourion", "url": "https://en.wikipedia.org/wiki/Kourion", "quote": "The Kingdom of Kourion, a Southern Cypriot kingdom, was established during the Cypro-Geometric period (CG) (1050–750 BCE)", "outcome": "found"}, {"source": "https://www.ancientcyprus.com/sites/kourion", "url": "https://www.ancientcyprus.com/sites/kourion", "quote": "The earliest substantial evidence for the city-kingdom comes from the Cypro-Geometric period (c. 1050–750 BCE)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0020)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and ancientcyprus.com both place the establishment and earliest substantial evidence of the Kourion city-kingdom at the start of the Cypro-Geometric period, c. 1050 BCE (matching Wikidata P571), so the start lies in 1500 - 500 BC, not in the stored 3000 - 1500 BC bucket; the Neolithic-Bronze Age sites of the Kouris valley (Sotira, Erimi, Episkopi-Bamboula) are other sites.", "value_page": null}]'::jsonb),
    ('99b1e4ac-3157-4120-b015-8f72d9c9fe35'::uuid, 'site_type', 'Temple complex', 'Temple', 'fields-wd1-2026-09-26b-s007:99b1e4ac-3157-4120-b015-8f72d9c9fe35:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Temple complex'' -> ''Temple''', '[{"source": "https://www.routledge.com/Dilmun-Temple-At-Saar-Bahrain-and-its-Archaeological-Inheritance/Crawford-Killick-Moon/p/book/9781138967700", "url": "https://www.routledge.com/Dilmun-Temple-At-Saar-Bahrain-and-its-Archaeological-Inheritance/Crawford-Killick-Moon/p/book/9781138967700", "quote": "The discovery and excavation of this settlement and its associated temple represent important additions to the archaeological heritage of Bahrain", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Sar,_Bahrain", "url": "https://en.wikipedia.org/wiki/Sar,_Bahrain", "quote": "Saar is the site of a temple, known as \"Saar Temple\", built during the Dilmun era of Bahrain''s history.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "CONFLICT", "reasoning": "The sources describe one temple (a single trapezoidal building 17.5 m long, rebuilt in place) standing at the top of the Saar settlement, not a complex of temples, so the specific type Temple replaces Temple complex.", "value_page": null}]'::jsonb),
    ('99b1e4ac-3157-4120-b015-8f72d9c9fe35'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Sar,_Bahrain', 'https://journals.uclpress.co.uk/ai/article/280/galley/12429/download/', 'fields-wd1-2026-09-26b-s007:99b1e4ac-3157-4120-b015-8f72d9c9fe35:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Sar,_Bahrain'' -> ''https://journals.uclpress.co.uk/ai/article/280/galley/12429/download/''', '[{"source": "https://journals.uclpress.co.uk/ai/article/280/galley/12429/download/", "url": "https://journals.uclpress.co.uk/ai/article/280/galley/12429/download/", "quote": "Aerial view of the Saar temple", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Sar,_Bahrain", "url": "https://en.wikipedia.org/wiki/Sar,_Bahrain", "quote": "Saar is the site of a temple, known as \"Saar Temple\", built during the Dilmun era of Bahrain''s history.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the modern town of Saar; no article on the temple exists, so the excavator Harriet Crawford''s open-access report ''Dilmun revisited: excavations at Saar, Bahrain'' (Archaeology International), which describes the Saar temple and settlement, is the page about this very site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('99c67365-3376-46ae-9e60-0d2ec03bfff4'::uuid, 'site_type', 'Rock relief/carving', 'Well', 'fields-wd1-2026-09-26b-s007:99c67365-3376-46ae-9e60-0d2ec03bfff4:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Rock relief/carving'' -> ''Well''', '[{"source": "https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N7931", "url": "https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N7931", "quote": "In Horsley''s day (c.1732), a rectangular well was visible here cased with masonry.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=8290", "url": "https://www.megalithic.co.uk/article.php?sid=8290", "quote": "Type: Holy Well or Sacred Spring", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0033)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Northumberland HER describes a masonry-cased rectangular well at the centre of a shrine, and the Megalithic Portal classes the site as a holy well or sacred spring. Neither describes a rock relief. The relief of Coventina is a find from the well and is kept at Chesters Museum.", "value_page": null}]'::jsonb),
    ('99c67365-3376-46ae-9e60-0d2ec03bfff4'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Coventina', 'https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N7931', 'fields-wd1-2026-09-26b-s007:99c67365-3376-46ae-9e60-0d2ec03bfff4:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Coventina'' -> ''https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N7931''', '[{"source": "https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N7931", "url": "https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N7931", "quote": "Temple (site of). Coventina''s Well. Altars and Hoard of coins found AD 1876.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=8290", "url": "https://www.megalithic.co.uk/article.php?sid=8290", "quote": "Site Name: Coventina''s Well Country: England County: Northumberland", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0033)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the goddess Coventina, not the site, and the well has no Wikipedia article of its own. Keys to the Past record N7931, the Durham and Northumberland HER entry, is about Coventina''s Well itself, and the Megalithic Portal names the same site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
