    ('9abf8d9a-b474-44cf-b9da-1761e7a6d1ad'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Mortuary_temple', 'https://en.wikipedia.org/wiki/Precinct_of_Amun-Re', 'fields-wd1-2026-09-26b-s007:9abf8d9a-b474-44cf-b9da-1761e7a6d1ad:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Mortuary_temple'' -> ''https://en.wikipedia.org/wiki/Precinct_of_Amun-Re''', '[{"source": "https://en.wikipedia.org/wiki/Precinct_of_Amun-Re", "url": "https://en.wikipedia.org/wiki/Precinct_of_Amun-Re", "quote": "The Temple of Amun is the principle structure of the Precinct.", "outcome": "found"}, {"source": "https://digitalkarnak.ucsc.edu/Middle-Kingdom-Court/", "url": "https://digitalkarnak.ucsc.edu/Middle-Kingdom-Court/", "quote": "Senusret I built a limestone temple dedicated to the god Amun-Ra at Karnak, probably replacing a much smaller sandstone temple on the same location.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0024)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the generic article on mortuary temples, not about this site; the site''s Wikidata item has no Wikipedia article, and English Wikipedia covers the Temple of Amun at Karnak in its Precinct of Amun-Re article, whose principal structure it is; UCSC''s Digital Karnak describes the same temple of Amun-Ra at Karnak.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Precinct of Amun-Re", "unreadable": false, "wikibase_item": "Q1306397"}}]'::jsonb),
