    ('9b3a978b-e3d2-4257-845e-a435d92bd535'::uuid, 'site_type', 'City/town/settlement', 'Settlement', 'fields-wd1-2026-09-26b-s007:9b3a978b-e3d2-4257-845e-a435d92bd535:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''City/town/settlement'' -> ''Settlement''', '[{"source": "https://en.wikipedia.org/wiki/T%C3%B8nnesminde", "url": "https://en.wikipedia.org/wiki/T%C3%B8nnesminde", "quote": "Recent excavations suggest that Tønnesminde contains settlements dating from the Funnelbeaker culture", "outcome": "found"}, {"source": "https://www.kulturarv.dk/fundogfortidsminder/Lokalitet/198036/", "url": "https://www.kulturarv.dk/fundogfortidsminder/Lokalitet/198036/", "quote": "Bosættelse, uspec undergruppe, Jernalder (dateret 100 f.Kr. - 1066 e.Kr.)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0022)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia describes Tønnesminde as a multi-period settlement site and the Danish register records it as a settlement (bosættelse) with Iron Age pits and Viking Age pit houses; it is a rural settlement, not a city or town, so the specific type Settlement fits better than City/town/settlement.", "value_page": null}]'::jsonb),
    ('9b42d08a-5048-42bb-8527-8e26a4f6bbe2'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd1-2026-09-26b-s007:9b42d08a-5048-42bb-8527-8e26a4f6bbe2:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('9b42d08a-5048-42bb-8527-8e26a4f6bbe2'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26b-s007:9b42d08a-5048-42bb-8527-8e26a4f6bbe2:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0018)", "decision": "clear", "status": "MISSING", "reasoning": "The Institute of Archaeology (IARH) and the Histria Antiqua topography article show Sotin was first settled in the Eneolithic (Baden culture, with Neolithic finds), long before the stored 500 BC, but no source about the site dates that first occupation by year, century or millennium; the dated statements (Dalj-group burials of the 8th century BC, the Roman fort of the 1st century AD) are later phases, so the start cannot be sourced and the field is emptied.", "value_page": null}]'::jsonb),
    ('9b4bc2f9-521a-467f-a1a6-ebd4563221e9'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26b-s007:9b4bc2f9-521a-467f-a1a6-ebd4563221e9:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('9b4bc2f9-521a-467f-a1a6-ebd4563221e9'::uuid, 'period_start', '-1000', NULL, 'fields-wd1-2026-09-26b-s007:9b4bc2f9-521a-467f-a1a6-ebd4563221e9:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0047)", "decision": "clear", "status": "MISSING", "reasoning": "The sources call Walbury Camp an Early Iron Age hillfort but none found gives a year or century for its construction (only a general 700-300 BC date for British hillforts on one local-history page), so no two independent sources date the start and the stored -1000 is cleared.", "value_page": null}]'::jsonb),
    ('9b4bc2f9-521a-467f-a1a6-ebd4563221e9'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26b-s007:9b4bc2f9-521a-467f-a1a6-ebd4563221e9:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://en.wikipedia.org/wiki/Walbury_Hill", "url": "https://en.wikipedia.org/wiki/Walbury_Hill", "quote": "On the hill''s summit is the Iron Age hill fort of Walbury Camp", "outcome": "found"}, {"source": "https://www.digitaldigging.net/walbury-camp-hill-fort-berkshire/", "url": "https://www.digitaldigging.net/walbury-camp-hill-fort-berkshire/", "quote": "Walbury Camp is a large univallate Early Iron Age hillfort of around 82 acres (33 hectares), making it the largest in Berkshire.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4529", "url": "https://www.megalithic.co.uk/article.php?sid=4529", "quote": "The highest chalk hill in Britain is capped by Walbury Hillfort, the largest one in Berkshire.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0047)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, Digital Digging and the Megalithic Portal all describe the site as an Iron Age hill fort (univallate, 33 ha); Fort is the most specific canonical type, not a fortress or citadel.", "value_page": null}]'::jsonb),
    ('9b4bc2f9-521a-467f-a1a6-ebd4563221e9'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Walbury_Hill', 'https://www.megalithic.co.uk/article.php?sid=4529', 'fields-wd1-2026-09-26b-s007:9b4bc2f9-521a-467f-a1a6-ebd4563221e9:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Walbury_Hill'' -> ''https://www.megalithic.co.uk/article.php?sid=4529''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=4529", "url": "https://www.megalithic.co.uk/article.php?sid=4529", "quote": "The highest chalk hill in Britain is capped by Walbury Hillfort, the largest one in Berkshire.", "outcome": "found"}, {"source": "https://www.digitaldigging.net/walbury-camp-hill-fort-berkshire/", "url": "https://www.digitaldigging.net/walbury-camp-hill-fort-berkshire/", "quote": "Walbury Camp is a large univallate Early Iron Age hillfort of around 82 acres (33 hectares), making it the largest in Berkshire.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0047)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the hill (Walbury Camp only redirects to it and gets one sentence); the Megalithic Portal record ''Walbury Camp Hillfort'' is about the fort itself and loads as plain HTML, while the Historic England list entry refuses automated requests.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
