    ('9bec7da2-8ff6-46be-a2cf-34d689358bf2'::uuid, 'site_type', 'Megalithic structures', 'Monument', 'fields-wd1-2026-09-26b-s007:9bec7da2-8ff6-46be-a2cf-34d689358bf2:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Megalithic structures'' -> ''Monument''', '[{"source": "https://www.agathe.gr/id/agora/monument/south%20stoa%20i", "url": "https://www.agathe.gr/id/agora/monument/south%20stoa%20i", "quote": "Monument: South Stoa I", "outcome": "found"}, {"source": "https://perseus-aa.github.io/items/aa_71.html", "url": "https://perseus-aa.github.io/items/aa_71.html", "quote": "Stoa; on the south side of the Agora, between the Heliaia and the Enneakrounos (SE Fountainhouse).", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/South_Stoa_I_(Athens)", "url": "https://en.wikipedia.org/wiki/South_Stoa_I_(Athens)", "quote": "The South Stoa I of Athens was a two-aisled stoa located on the south side of the Agora, in Athens, Greece, between the Aiakeion and the Southeast Fountain House.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0071)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Agora excavations database classes South Stoa I as a monument of civic and commercial function, and Perseus and Wikipedia describe it as a two-aisled stoa (a colonnaded public building with dining rooms for officials) on the south side of the Agora; it is a public building, not megalithic structures, and Monument is the canonical type that holds.", "value_page": null}]'::jsonb),
    ('9bf7ac31-4f48-4bbc-ad4b-cbef11d994b9'::uuid, 'site_type', 'City/town/settlement', 'Settlement', 'fields-wd1-2026-09-26b-s007:9bf7ac31-4f48-4bbc-ad4b-cbef11d994b9:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''City/town/settlement'' -> ''Settlement''', '[{"source": "https://en.wikipedia.org/wiki/Huckhoe_Settlement", "url": "https://en.wikipedia.org/wiki/Huckhoe_Settlement", "quote": "This is thought to be a re-occupation in the Romano-British period, of an Iron Age defended settlement.", "outcome": "found"}, {"source": "https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N10579", "url": "https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N10579", "quote": "Palisaded enclosure/settlement, securely dated by carbon-14 to 510+/-40bc.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0036)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Northumberland HER describe Huckhoe as a palisaded enclosure and defended settlement reoccupied as a Romano-British settlement (the HER notes its defences were never of hillfort order); the most specific canonical type is Settlement, not the combined city/town/settlement.", "value_page": null}]'::jsonb),
