    ('9c35081a-a345-4545-962d-d3aeeb2f2b0c'::uuid, 'period_start', '-1500', NULL, 'fields-wd1-2026-09-26b-s007:9c35081a-a345-4545-962d-d3aeeb2f2b0c:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-1500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0057)", "decision": "clear", "status": "MISSING", "reasoning": "The Zeitreise Gilching society dates the barrows of Gilching to the Middle and Late Bronze Age (1600-1300 BC) and the Hallstatt period (800-600 BC), the English Wikipedia calls them Celtic tumuli, and the Bavarian monument list records most as of undetermined prehistoric date. Only one source family gives a year, and it does not fall in the stored bucket, so the field is emptied.", "value_page": null}]'::jsonb),
    ('9c35081a-a345-4545-962d-d3aeeb2f2b0c'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Gilching', 'https://www.zeitreise-gilching.de/ortsgeschichte/bronzezeit/hugelgraber/', 'fields-wd1-2026-09-26b-s007:9c35081a-a345-4545-962d-d3aeeb2f2b0c:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Gilching'' -> ''https://www.zeitreise-gilching.de/ortsgeschichte/bronzezeit/hugelgraber/''', '[{"source": "https://www.zeitreise-gilching.de/ortsgeschichte/bronzezeit/hugelgraber/", "url": "https://www.zeitreise-gilching.de/ortsgeschichte/bronzezeit/hugelgraber/", "quote": "Hügelgräber auf Gilchinger Gemeindegebiet", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Gilching", "url": "https://en.wikipedia.org/wiki/Gilching", "quote": "Celtic tumuli and nemetons are found in the nearby forest between Gilching and Schöngeising", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0057)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the municipality of Gilching; the Zeitreise Gilching page ''Hügelgräber'' is about the barrows on Gilching''s territory themselves, which the Wikipedia article also mentions.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
