    ('9cb2bfc1-76b9-4904-941d-0d3cc7f86d6a'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26b-s007:9cb2bfc1-76b9-4904-941d-0d3cc7f86d6a:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://en.wikipedia.org/wiki/Rapidum", "url": "https://en.wikipedia.org/wiki/Rapidum", "quote": "Rapidum was a Roman settlement and fort located in Mauretania Caesariensis, nearly 100 km south of Icosium (Algiers).", "outcome": "found"}, {"source": "https://journals.openedition.org/encyclopedieberbere/4421", "url": "https://journals.openedition.org/encyclopedieberbere/4421", "quote": "La seconde cohorte des Sardes établit son camp en 122", "outcome": "found"}, {"source": "https://cartes.patrimoineculturelalgerien.org/fr/lieu/26-m%C3%A9d%C3%A9a/451", "url": "https://cartes.patrimoineculturelalgerien.org/fr/lieu/26-m%C3%A9d%C3%A9a/451", "quote": "a été crée en 122 au temps de l’empereur Publius Aelius Hadrianus qui régna entre 117 et 138 de notre ère, le camp comportant 500 militaires (380 fantassins et 120 cavaliers)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "Rapidum was founded as the auxiliary camp (fort) of the Cohors II Sardorum, and the civil settlement grew up beside it; sources call it a Roman fort or military camp, never a fortress or citadel, so the canonical type is Fort.", "value_page": null}]'::jsonb),
    ('9cb8e16e-1f97-47da-b7f9-558216c9b543'::uuid, 'site_type', 'Archaeological site', NULL, 'fields-wd1-2026-09-26b-s007:9cb8e16e-1f97-47da-b7f9-558216c9b543:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''Archaeological site'' -> None', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0010)", "decision": "clear", "status": "CONFLICT", "reasoning": "The readable sources (Greek Ministry of Culture, Pleiades, ToposText, Wikipedia) describe the Chalkotheke as a storage building or treasury for the bronze votive offerings of Athena, of which only bedrock cuttings and foundation fragments survive; no canonical type names a storehouse, and no two independent readable sources classify it as an archaeological site or as any other canonical type, so the stored generic value cannot be confirmed and no replacement can be sourced.", "value_page": null}]'::jsonb),
    ('9d230dae-1f9b-4d16-a2a0-cce28ff32c56'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Cetina', 'https://en.wikipedia.org/wiki/Cetina_culture', 'fields-wd1-2026-09-26b-s007:9d230dae-1f9b-4d16-a2a0-cce28ff32c56:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Cetina'' -> ''https://en.wikipedia.org/wiki/Cetina_culture''', '[{"source": "https://en.wikipedia.org/wiki/Cetina_culture", "url": "https://en.wikipedia.org/wiki/Cetina_culture", "quote": "It is named after the numerous sites along the Cetina river in Central Dalmatia", "outcome": "found"}, {"source": "https://www.enciklopedija.hr/clanak/cetinska-kultura", "url": "https://www.enciklopedija.hr/clanak/cetinska-kultura", "quote": "cetinska kultura, kultura ranoga brončanog doba (1900. do 1600. pr. Kr.), nazvana prema mnogobrojnim nalazištima uz rijeku Cetinu", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0017)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the river; the entry''s mound sites along the Cetina are the eponymous sites of the Cetina culture, whose English Wikipedia article (named after the numerous sites along the Cetina river, as the Hrvatska enciklopedija also says) describes them and their tumuli.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Cetina culture", "unreadable": false, "wikibase_item": "Q12628856"}}]'::jsonb),
