    ('9d65d8dd-ef7f-4479-ad2b-1fde36484e23'::uuid, 'period_start', '-500', '-1320', 'fields-wd1-2026-09-26b-s007:9d65d8dd-ef7f-4479-ad2b-1fde36484e23:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''-500'' -> ''-1320''', '[{"source": "https://helladic.info/MAPC/pkey_report_wparam.php?place=C529", "url": "https://helladic.info/MAPC/pkey_report_wparam.php?place=C529", "quote": "LH IIIB: (1320 BC - 1190 BC)", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Temple_of_Athena_Alea", "url": "https://en.wikipedia.org/wiki/Temple_of_Athena_Alea", "quote": "It served as the focal point of a significant area already from tenth century BC", "outcome": "found"}, {"source": "https://www.worldhistory.org/Tegea/", "url": "https://www.worldhistory.org/Tegea/", "quote": "The sanctuary site shows evidence of cult worship dating back to the 10th century BCE as indicated by the presence of votive offerings.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0072)", "decision": "replace", "status": "MISSING", "reasoning": "The Mycenaean Atlas records LH IIIB pottery (stirrup-jars, 1320-1190 BC) and a prehistoric settlement at the temple site before the shrine, and Wikipedia and World History Encyclopedia date the sanctuary''s cult to the 10th century BC; both lie in 1500 - 500 BC, not in the stored 500 BC - 1 AD (Tegea fought Sparta c. 560 BC), so the start is replaced with -1320.", "value_page": null}]'::jsonb),
