    ('9dcc1c87-49c7-44f9-9d09-13b9b2b6671f'::uuid, 'period_start', '-1500', NULL, 'fields-wd1-2026-09-26b-s007:9dcc1c87-49c7-44f9-9d09-13b9b2b6671f:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-1500'' -> None', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0005)", "decision": "clear", "status": "MISSING", "reasoning": "The sources disagree on when the Beacon Hill (Burghclere) hillfort began: the Wikipedia article says the camp was built around 1000 BC, while the Historic England scheduling calls it a large univallate Iron Age hillfort and the Hampshire Chronicle says the fort was probably occupied between the 5th and 1st centuries BC; the fort was never systematically excavated, so no two independent readable sources agree on a start in one bucket.", "value_page": null}]'::jsonb),
