    ('9e2b99df-4b4c-41cb-80d3-879a5812e7ed'::uuid, 'site_type', 'Temple complex', 'Church', 'fields-wd1-2026-09-26b-s007:9e2b99df-4b4c-41cb-80d3-879a5812e7ed:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Temple complex'' -> ''Church''', '[{"source": "https://gcatholic.org/churches/africa/142875", "url": "https://gcatholic.org/churches/africa/142875", "quote": "Type: Former Church", "outcome": "found"}, {"source": "https://fr.wikipedia.org/wiki/Basilique_Sainte-Crispine", "url": "https://fr.wikipedia.org/wiki/Basilique_Sainte-Crispine", "quote": "La basilique Sainte-Crispine de Tébessa, est une église chrétienne du IVe siècle située à Tébessa en Algérie.", "outcome": "found"}, {"source": "https://www.newadvent.org/cathen/14634a.htm", "url": "https://www.newadvent.org/cathen/14634a.htm", "quote": "Tebessa is very rich in ancient monuments, among them being a triumphal arch of Caracalla, a temple, a Christian basilica of the fourth century 216 feet long by 72 feet wide, near which are buried a number of pious persons.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "GCatholic lists the Basilica of St Crispina as a former church, French Wikipedia calls it a Christian church and the Catholic Encyclopedia a Christian basilica: it is an early Christian church (pilgrimage basilica), not a pagan temple complex.", "value_page": null}]'::jsonb),
