    ('9e34acd6-6cb0-44f1-bf20-97d250838359'::uuid, 'period_start', '-3000', NULL, 'fields-wd1-2026-09-26b-s007:9e34acd6-6cb0-44f1-bf20-97d250838359:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-3000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0033)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia, stone-circles.org.uk and the Bolsterstone survey date the carving only to ''the late Neolithic or Bronze Age'', with no year, century or millennium. The Historic England entry cannot be read. No two sources date the start in a form the field can carry.", "value_page": null}]'::jsonb),
    ('9e34acd6-6cb0-44f1-bf20-97d250838359'::uuid, 'site_type', 'Rock relief/carving', 'Rock art', 'fields-wd1-2026-09-26b-s007:9e34acd6-6cb0-44f1-bf20-97d250838359:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Rock relief/carving'' -> ''Rock art''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=10278", "url": "https://www.megalithic.co.uk/article.php?sid=10278", "quote": "Site Name: Ecclesall Woods Country: England County: Yorkshire (South) Type: Rock Art", "outcome": "found"}, {"source": "http://www.stone-circles.org.uk/stone/ecclesall.htm", "url": "http://www.stone-circles.org.uk/stone/ecclesall.htm", "quote": "is the most eastern example of rock art in the Yorkshire area.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0033)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a boulder carved with cup-and-ring marks, ovals and grooves. The Megalithic Portal classes it as rock art and stone-circles.org.uk describes it as carved rock / rock-art. Rock art is the specific canonical type for prehistoric cup-and-ring carving, not Rock relief/carving.", "value_page": null}]'::jsonb),
    ('9e34acd6-6cb0-44f1-bf20-97d250838359'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Ecclesall_Woods', 'https://www.megalithic.co.uk/article.php?sid=10278', 'fields-wd1-2026-09-26b-s007:9e34acd6-6cb0-44f1-bf20-97d250838359:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Ecclesall_Woods'' -> ''https://www.megalithic.co.uk/article.php?sid=10278''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=10278", "url": "https://www.megalithic.co.uk/article.php?sid=10278", "quote": "Site Name: Ecclesall Woods Country: England County: Yorkshire (South) Type: Rock Art", "outcome": "found"}, {"source": "http://www.stone-circles.org.uk/stone/ecclesall.htm", "url": "http://www.stone-circles.org.uk/stone/ecclesall.htm", "quote": "Ecclesall Wood Neolithic / Bronze Age Carved Rock", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0033)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the whole woodland, not the carved rock. The Historic England list entry refuses automated requests and planning.data.gov.uk holds only the monument''s name and outline. The Megalithic Portal''s page is a readable page about this rock art panel itself, and stone-circles.org.uk describes the same carved rock, found in 1981.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('9e827a4b-0855-4414-946b-b5fc3e3efb9b'::uuid, 'site_type', 'Megalithic structures', 'Monument', 'fields-wd1-2026-09-26b-s007:9e827a4b-0855-4414-946b-b5fc3e3efb9b:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Megalithic structures'' -> ''Monument''', '[{"source": "https://en.wikipedia.org/wiki/Cnidian_Treasury", "url": "https://en.wikipedia.org/wiki/Cnidian_Treasury", "quote": "described the monument but was puzzled by its architrave inscription", "outcome": "found"}, {"source": "https://perseus-aa.github.io/items/aa_169.html", "url": "https://perseus-aa.github.io/items/aa_169.html", "quote": "Temple-like building; in the southern half of the Sanctuary of Apollo, east of the point where the Sacred Way 1st curves and ascends to the northeast.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0063)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Cnidian Treasury is a small Ionic marble treasury building, temple-like in form, in the Sanctuary of Apollo at Delphi (Perseus), and Wikipedia calls it ''the monument'' described by Pausanias. It is not megalithic. With no treasury type in the canonical list, and ''Religious'' stated by no quotable source, Monument is the most specific type the sources support.", "value_page": null}]'::jsonb),
    ('9e91dedc-7e74-4056-8dcc-ad340cb8e92b'::uuid, 'period_name', '3000 - 1500 BC', NULL, 'fields-wd1-2026-09-26b-s007:9e91dedc-7e74-4056-8dcc-ad340cb8e92b:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('9e91dedc-7e74-4056-8dcc-ad340cb8e92b'::uuid, 'period_start', '-3000', NULL, 'fields-wd1-2026-09-26b-s007:9e91dedc-7e74-4056-8dcc-ad340cb8e92b:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-3000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0102)", "decision": "clear", "status": "MISSING", "reasoning": "Only one source family dates Chakdara''s start: the University of Peshawar report ''Excavation at Damkot'' (Ancient Pakistan IV) puts the earliest settlement in the early 1st millennium BC. That contradicts the stored 3000-1500 BC bucket. Wikipedia gives only ''3,500 years'', and no second independent source with a year could be found, so the field is cleared rather than left wrong.", "value_page": null}]'::jsonb),
    ('9ed175c7-a706-4a71-b10a-f93a68734afc'::uuid, 'period_name', '< 4500 BC', NULL, 'fields-wd1-2026-09-26b-s007:9ed175c7-a706-4a71-b10a-f93a68734afc:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('9ed175c7-a706-4a71-b10a-f93a68734afc'::uuid, 'period_start', '-5000', NULL, 'fields-wd1-2026-09-26b-s007:9ed175c7-a706-4a71-b10a-f93a68734afc:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-5000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0155)", "decision": "clear", "status": "MISSING", "reasoning": "The stored -5000 (before 4500 BC) is too early for any Neolithic date, but nobody has dated the cairn itself: Cadw only says it is ''presumed to be of Neolithic date (c4500-2300BC)'' from the burials in the adjacent Gop Cave and parallels in Ireland, and the Clwyd-Powys Archaeological Trust says it is ''assumed to belong to the same period''. No two independent sources date its start, so the field is cleared.", "value_page": null}]'::jsonb),
    ('9ed175c7-a706-4a71-b10a-f93a68734afc'::uuid, 'site_type', 'Fortress/citadel', 'Cairn', 'fields-wd1-2026-09-26b-s007:9ed175c7-a706-4a71-b10a-f93a68734afc:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Fortress/citadel'' -> ''Cairn''', '[{"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2829", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2829", "quote": "The monument comprises a enormous limestone cairn occupying the summit of a prominent E-W limestone ridge and commanding extensive views in all directions.", "outcome": "found"}, {"source": "https://coflein.gov.uk/en/sites/306725", "url": "https://coflein.gov.uk/en/sites/306725", "quote": "Gop Cairn is a titanic cairn, 75-80m in diameter and 12m high, centrally disturbed.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0155)", "decision": "replace", "status": "CONFLICT", "reasoning": "Cadw (scheduled monument FL007 Gop Cairn, site type Cairn) and the RCAHMW Coflein record (NPRN 306725, type CAIRN) both describe a huge limestone cairn with no burial chamber found; nothing describes a fortress or citadel, so the type is Cairn.", "value_page": null}]'::jsonb),
    ('9ef004b4-0fe9-48c5-9f93-d8476487bb6e'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Hawara', 'https://de.wikipedia.org/wiki/Hawara-Pyramide', 'fields-wd1-2026-09-26b-s007:9ef004b4-0fe9-48c5-9f93-d8476487bb6e:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Hawara'' -> ''https://de.wikipedia.org/wiki/Hawara-Pyramide''', '[{"source": "https://de.wikipedia.org/wiki/Hawara-Pyramide", "url": "https://de.wikipedia.org/wiki/Hawara-Pyramide", "quote": "Die Hawara-Pyramide ist das Grabmal des altägyptischen Königs Amenemhet III. aus der 12. Dynastie im Mittleren Reich.", "outcome": "found"}, {"source": "https://www.historyhit.com/locations/hawara-pyramid/", "url": "https://www.historyhit.com/locations/hawara-pyramid/", "quote": "The Hawara Pyramid was erected by the Twelfth Dynasty pharaoh, Amenemhat III, ruler of Ancient Egypt from around 1860 BC to 1814 BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0023)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia''s ''Hawara'' is the article of the village and necropolis in which the pyramid lies; English Wikipedia has no article of its own on the pyramid, but German Wikipedia''s ''Hawara-Pyramide'' (sitelink of the pyramid''s Wikidata item Q11818430) is about this very monument, the tomb of Amenemhat III.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Hawara-Pyramide", "unreadable": false, "wikibase_item": "Q11818430"}}]'::jsonb),
    ('9f230ad4-cb35-4ba9-8552-ba1e4b4fae40'::uuid, 'site_type', 'Megalithic structures', 'Reservoir/aqueduct/canal', 'fields-wd1-2026-09-26b-s007:9f230ad4-cb35-4ba9-8552-ba1e4b4fae40:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Megalithic structures'' -> ''Reservoir/aqueduct/canal''', '[{"source": "https://esparragalejo.es/historia/", "url": "https://esparragalejo.es/historia/", "quote": "construyeron una presa, de cuyo embalse se abastecía el campamento, a través de un acueducto.", "outcome": "found"}, {"source": "https://staff.civil.uq.edu.au/h.chanson/arch_dam.html", "url": "https://staff.civil.uq.edu.au/h.chanson/arch_dam.html", "quote": "Another unusual Roman dam was the Esparragalejo dam, near Merida (Spain).", "outcome": "found"}, {"source": "https://www.unrv.com/articles/roman-dams-how-engineers-controlled-water.php", "url": "https://www.unrv.com/articles/roman-dams-how-engineers-controlled-water.php", "quote": "Other Spanish structures, including dams at Consuegra, Esparragalejo, Muel, and Alcantarilla, illustrate different approaches to buttressing, embankment support, river diversion, and reservoir storage.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0131)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a Roman multiple-arch buttress dam that impounded a reservoir (the Charca Grande) feeding the Roman camp through an aqueduct, not a megalithic structure; Reservoir/aqueduct/canal is the most specific canonical type for a Roman dam and its reservoir.", "value_page": null}]'::jsonb),
    ('9f328a68-b73d-4fd9-bc44-a78d3cae960c'::uuid, 'site_type', 'Fortress/citadel', 'Town', 'fields-wd1-2026-09-26b-s007:9f328a68-b73d-4fd9-bc44-a78d3cae960c:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Fortress/citadel'' -> ''Town''', '[{"source": "https://www.roman-britain.co.uk/places/isca-dumnoniorum-exeter-town/", "url": "https://www.roman-britain.co.uk/places/isca-dumnoniorum-exeter-town/", "quote": "Isca Dumnoniorum was the Civitas Capital of the Dumnonii. Around 75AD work on the town’s forum and basilica had begun on the site of the former principia", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Isca_Dumnoniorum", "url": "https://en.wikipedia.org/wiki/Isca_Dumnoniorum", "quote": "The town grew up around this fortress and served as the tribal capital of the Dumnonians under and after the Romans.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0037)", "decision": "replace", "status": "CONFLICT", "reasoning": "The legionary fortress stood only c. AD 55-75; Isca Dumnoniorum, the name of the Dumnonian civitas capital, was the Roman town that replaced it and whose walls survive (roman-britain.co.uk; Wikipedia; Wikidata: Roman city), so Town fits better than Fortress/citadel.", "value_page": null}]'::jsonb),
    ('9f99919a-d5d6-4384-994b-704ece327ab6'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26b-s007:9f99919a-d5d6-4384-994b-704ece327ab6:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('9f99919a-d5d6-4384-994b-704ece327ab6'::uuid, 'period_start', '-4000', NULL, 'fields-wd1-2026-09-26b-s007:9f99919a-d5d6-4384-994b-704ece327ab6:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-4000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0070)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and the Ephorate of Antiquities of Argolida only say the area was inhabited since the Neolithic period, with no year, century or millennium; no source dates the start in a quotable form, so the field is emptied.", "value_page": null}]'::jsonb),
