    ('9fe61c60-5565-4dfd-99c8-3b51f0396dfd'::uuid, 'period_name', '1 - 500 AD', '500 - 1000 AD', 'fields-wd1-2026-09-26b-s007:9fe61c60-5565-4dfd-99c8-3b51f0396dfd:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start 601 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(601) = ''500 - 1000 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('9fe61c60-5565-4dfd-99c8-3b51f0396dfd'::uuid, 'period_start', '1', '601', 'fields-wd1-2026-09-26b-s007:9fe61c60-5565-4dfd-99c8-3b51f0396dfd:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''1'' -> ''601''', '[{"source": "https://en.wikipedia.org/wiki/Dungur", "url": "https://en.wikipedia.org/wiki/Dungur", "quote": "Dungur (or Dungur ''Addi Kilte) is a historic site dated to the 7th century CE, located in the city of Axum in modern Ethiopia.", "outcome": "found"}, {"source": "https://madainproject.com/dungur", "url": "https://madainproject.com/dungur", "quote": "Archaeological evidence indicates that Dungur was occupied primarily during the later phase of the Aksumite Kingdom, circa 600 CE to 940 CE", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0050)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia dates the building to the 7th century CE (Anfray''s excavations) and the Madain Project dates its occupation from c. 600 CE; the start belongs in the 500 - 1000 AD bucket, not the stored 1 - 500 AD one.", "value_page": null}]'::jsonb),
