    ('a25850c8-b73b-4eed-9eff-8fc6dc28ff73'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26b-s007:a25850c8-b73b-4eed-9eff-8fc6dc28ff73:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0011)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia (and its copies) give occupation from about 400 BC, but the 2000-2002 excavation report by Runggaldier finds occupation from the Early Preclassic (a Swasey-complex sherd) without giving a year; no two independent sources date the start to one year, so the field is emptied.", "value_page": null}]'::jsonb),
    ('a25850c8-b73b-4eed-9eff-8fc6dc28ff73'::uuid, 'site_type', 'Temple complex', 'City/town/settlement', 'fields-wd1-2026-09-26b-s007:a25850c8-b73b-4eed-9eff-8fc6dc28ff73:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Temple complex'' -> ''City/town/settlement''', '[{"source": "https://en.wikipedia.org/wiki/Louisville,_Belize", "url": "https://en.wikipedia.org/wiki/Louisville,_Belize", "quote": "Some substantial artificial mounds at Louisville are the remains of an ancient city of the Maya civilization.", "outcome": "found"}, {"source": "https://archive.org/stream/louisville-runggaldier-2004-1/Louisville%20-%20Runggaldier%202004%20%281%29_djvu.txt", "url": "https://archive.org/stream/louisville-runggaldier-2004-1/Louisville%20-%20Runggaldier%202004%20%281%29_djvu.txt", "quote": "direct contact between this fairly small settlement", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0011)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia calls the Louisville mounds the remains of an ancient Maya city and the excavator Runggaldier calls it a fairly small settlement with two pyramids and scattered mound groups; the Gann temple is only one building, so the site is a City/town/settlement, not a temple complex.", "value_page": null}]'::jsonb),
    ('a25850c8-b73b-4eed-9eff-8fc6dc28ff73'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Louisville,_Belize', NULL, 'fields-wd1-2026-09-26b-s007:a25850c8-b73b-4eed-9eff-8fc6dc28ff73:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''https://en.wikipedia.org/wiki/Louisville,_Belize'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0011)", "decision": "clear", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the modern village; no Wikipedia article about the archaeological site exists, and the scholarly pages about it (Antiquity''s ''Recontextualizing Louisville'', the BAR monograph) cannot be loaded without a login or bot block, so no readable page about the site itself is left.", "value_page": null}]'::jsonb),
    ('a2704598-c3b7-4cbb-9fdc-4055c445cec1'::uuid, 'period_name', '1500 - 500 BC', '1 - 500 AD', 'fields-wd1-2026-09-26b-s007:a2704598-c3b7-4cbb-9fdc-4055c445cec1:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start 1 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('a2704598-c3b7-4cbb-9fdc-4055c445cec1'::uuid, 'period_start', '-1500', '1', 'fields-wd1-2026-09-26b-s007:a2704598-c3b7-4cbb-9fdc-4055c445cec1:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''-1500'' -> ''1''', '[{"source": "https://archivo.eluniversal.com.mx/notas/921270.html", "url": "https://archivo.eluniversal.com.mx/notas/921270.html", "quote": "Por asociación con las piezas, los restos óseos datan de los años 1 a 500 después de Cristo", "outcome": "found"}, {"source": "https://colimamedios.com/inah-analiza-piezas-de-panteon-prehispanico-en-colima/", "url": "https://colimamedios.com/inah-analiza-piezas-de-panteon-prehispanico-en-colima/", "quote": "Por asociación con la cerámica, se calcula que los restos óseos datan de los años 1 a 500 después de Cristo.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0095)", "decision": "replace", "status": "MISSING", "reasoning": "The INAH report (via El Universal) and a separate Televisa report on the excavation both date the shaft-tomb burials, through their Comala-style ceramics, to AD 1-500. The burials outside the tomb were dated only ''preliminarmente'' to 600 BC - 500 AD. The securely attested start, AD 1, lies in the 1 - 500 AD bucket, not in the stored 1500 - 500 BC bucket.", "value_page": null}]'::jsonb),
    ('a2704598-c3b7-4cbb-9fdc-4055c445cec1'::uuid, 'site_type', 'Cemetery', 'Tomb', 'fields-wd1-2026-09-26b-s007:a2704598-c3b7-4cbb-9fdc-4055c445cec1:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Cemetery'' -> ''Tomb''', '[{"source": "https://lugares.inah.gob.mx/en/node/5233", "url": "https://lugares.inah.gob.mx/en/node/5233", "quote": "There was a large number of these tombs in the Colima region.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Western_Mexico_shaft_tomb_tradition", "url": "https://en.wikipedia.org/wiki/Western_Mexico_shaft_tomb_tradition", "quote": "The sites of El Opeño and La Campana in Colima feature some shaft tombs", "outcome": "found"}, {"source": "https://artdaily.cc/news/68558/Mexican-archaeologists-find-a-1-500-year-old-shaft-tomb-in-the-state-of-Colima-", "url": "https://artdaily.cc/news/68558/Mexican-archaeologists-find-a-1-500-year-old-shaft-tomb-in-the-state-of-Colima-", "quote": "is the guardian of a shaft tomb discovered in the state of Colima by investigators of the National Institute of Anthropology and History (INAH)", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0017)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Wikidata item is the state of Colima, but the site itself is a Colima shaft tomb (tumba de tiro): INAH''s Colima page, Wikipedia''s shaft-tomb article and a news report on an INAH excavation all describe these as tombs (an underground shaft and burial chamber for a family or lineage), not a cemetery, so the type is Tomb.", "value_page": null}]'::jsonb),
    ('a2704598-c3b7-4cbb-9fdc-4055c445cec1'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Colima', 'https://www.megalithic.co.uk/article.php?sid=35244', 'fields-wd1-2026-09-26b-s007:a2704598-c3b7-4cbb-9fdc-4055c445cec1:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Colima'' -> ''https://www.megalithic.co.uk/article.php?sid=35244''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=35244", "url": "https://www.megalithic.co.uk/article.php?sid=35244", "quote": "Site Name: Colima - Eastern Shaft Tomb", "outcome": "found"}, {"source": "https://archivo.eluniversal.com.mx/notas/921270.html", "url": "https://archivo.eluniversal.com.mx/notas/921270.html", "quote": "Arqueólogos mexicanos hallaron un panteón prehispánico en la ciudad de Colima", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0095)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the state of Colima. The Megalithic Portal entry ''Colima - Eastern Shaft Tomb'' is about this very burial site and summarises INAH''s 2013 report; El Universal''s report on the same find confirms it. No Wikipedia or register entry exists for the site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('a2720609-acca-47c5-b778-15568e68a67e'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd1-2026-09-26b-s007:a2720609-acca-47c5-b778-15568e68a67e:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('a2720609-acca-47c5-b778-15568e68a67e'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26b-s007:a2720609-acca-47c5-b778-15568e68a67e:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0051)", "decision": "clear", "status": "MISSING", "reasoning": "The shelter''s first occupation is Aurignacian (Upper Palaeolithic), and the sources date it only as ''about 35,000 years ago'' (English and French Wikipedia, the museum and tourism pages), a form that cannot be read as a year; no source states a BC year, century or millennium for this site itself. The stored -500 (500 BC-1 AD) is certainly wrong, so the field is cleared rather than kept.", "value_page": null}]'::jsonb),
