    ('a2b571fa-4aa3-4c23-b5f0-13c5552ce870'::uuid, 'period_name', '1000 - 1500 AD', NULL, 'fields-wd1-2026-09-26b-s007:a2b571fa-4aa3-4c23-b5f0-13c5552ce870:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('a2b571fa-4aa3-4c23-b5f0-13c5552ce870'::uuid, 'period_start', '1000', NULL, 'fields-wd1-2026-09-26b-s007:a2b571fa-4aa3-4c23-b5f0-13c5552ce870:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0113)", "decision": "clear", "status": "MISSING", "reasoning": "The sources date the estate only through its builder, Huayna Capac (reign 1493-1525 per Niles; lifetime c. 1464-1525 per Wikipedia); no source gives a construction year, and the reign straddles the 1000-1500 and 1500+ buckets, so the stored 1000 cannot be kept or replaced from quotes.", "value_page": null}]'::jsonb),
    ('a2c6e1bf-1538-43c4-ad4a-65a0186193a7'::uuid, 'site_type', 'Museum', 'Burial', 'fields-wd1-2026-09-26b-s007:a2c6e1bf-1538-43c4-ad4a-65a0186193a7:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Museum'' -> ''Burial''', '[{"source": "https://en.wikipedia.org/wiki/North_Bersted_Man", "url": "https://en.wikipedia.org/wiki/North_Bersted_Man", "quote": "The North Bersted Man is the modern name given to a warrior found in a burial at excavations by the Thames Valley Archaeological services made in 2008 near North Bersted.", "outcome": "found"}, {"source": "https://archaeology.co.uk/articles/features/arms-and-the-man.htm", "url": "https://archaeology.co.uk/articles/features/arms-and-the-man.htm", "quote": "it was clear that the team had discovered an exceptional Iron Age warrior burial. Discovered in 2008, the North Bersted warrior’s grave was excavated by Thames Valley Archaeological services.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0042)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Current Archaeology describe the site as an Iron Age warrior burial excavated at North Bersted; the stored ''Museum'' is the Chichester museum that displays the finds, not the site.", "value_page": null}]'::jsonb),
    ('a2ceca93-fe33-44a6-abe3-de8c41424997'::uuid, 'site_type', 'Fortress/citadel', 'Fortification', 'fields-wd1-2026-09-26b-s007:a2ceca93-fe33-44a6-abe3-de8c41424997:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Fortress/citadel'' -> ''Fortification''', '[{"source": "https://en.wikipedia.org/wiki/Hagia_Photia", "url": "https://en.wikipedia.org/wiki/Hagia_Photia", "quote": "It was originally built in the Middle Minoan period with a surrounding fortification wall.", "outcome": "found"}, {"source": "http://www.minoancrete.com/agphotia.htm", "url": "http://www.minoancrete.com/agphotia.htm", "quote": "Although the building was surrounded by a fortification wall there is no evidence that it was attacked", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0066)", "decision": "replace", "status": "CONFLICT", "reasoning": "The sources describe a large rectangular Minoan building enclosed by a fortification wall, not a fortress or citadel; Fortification is the type their words support.", "value_page": null}]'::jsonb),
    ('a2e7ed0a-b619-4b9c-8626-6bfac777e811'::uuid, 'site_type', 'Residence/villa/farmhouse', 'Bath', 'fields-wd1-2026-09-26b-s007:a2e7ed0a-b619-4b9c-8626-6bfac777e811:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Residence/villa/farmhouse'' -> ''Bath''', '[{"source": "https://en.wikipedia.org/wiki/Shukhuti_mosaic", "url": "https://en.wikipedia.org/wiki/Shukhuti_mosaic", "quote": "is a bath mosaic discovered in 1961 at the village of Shukhuti", "outcome": "found"}, {"source": "https://www.krukowski-center.uw.edu.pl/research/dzalisi", "url": "https://www.krukowski-center.uw.edu.pl/research/dzalisi", "quote": "the village of Shukhuti (region of Guria, Western Georgia), which features Roman bathrooms in dating to 200-600 AD", "outcome": "found"}, {"source": "https://lanchkhuti.gov.ge/?p=898", "url": "https://lanchkhuti.gov.ge/?p=898", "quote": "მ.ხალვაშის საკარმიდამო ნაკვეთზე ნაპოვნი იქნა მე-5-6 საუკუნეების ციხე-სასახლის ნაშთები, რომაული აბანოს, ე.წ. “თერმა”-ს ტიპის ნანგრევები და აბანოს იატაკის მოზაიკური ფრაგმენტი", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0056)", "decision": "replace", "status": "CONFLICT", "reasoning": "What the mosaic marks is a Roman-type bath: English Wikipedia calls it a bath mosaic, the Krukowski Center speaks of Roman baths at Shukhuti, the Lanchkhuti municipality of the ruins of a Roman bath of the ''therma'' type with its mosaic floor, and the excavation report is titled ''The Shukhuti Bath''. The bath belonged to a residence, but only the Wikipedia family calls it a villa, so Bath is the most specific type that independent sources support.", "value_page": null}]'::jsonb),
    ('a3047874-7d9a-429c-ba0a-b2448e6e88e6'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26b-s007:a3047874-7d9a-429c-ba0a-b2448e6e88e6:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
