    ('a3047874-7d9a-429c-ba0a-b2448e6e88e6'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Tan_Hill%2C_Wiltshire', 'https://www.wiltshirewhitehorses.org.uk/tanhill.html', 'fields-wd1-2026-09-26b-s007:a3047874-7d9a-429c-ba0a-b2448e6e88e6:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Tan_Hill%2C_Wiltshire'' -> ''https://www.wiltshirewhitehorses.org.uk/tanhill.html''', '[{"source": "https://www.wiltshirewhitehorses.org.uk/tanhill.html", "url": "https://www.wiltshirewhitehorses.org.uk/tanhill.html", "quote": "There was once a white horse, or possibly a donkey, on Tan Hill in the parish of All Cannings. Until recently there had been little evidence for the existence of the figure, and some authorities had doubted its existence. The only direct evidence had come from the author Kathleen Wiltshire. In Wiltshire Folklore", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Tan_Hill,_Wiltshire", "url": "https://en.wikipedia.org/wiki/Tan_Hill,_Wiltshire", "quote": "Formerly, Tan Hill had a hill figure of a white horse, sometimes called the Tan Hill Donkey because of its notably large head. Author Kathleen Wiltshire, in her book Wiltshire Folklore", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0046)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the hill; the Wiltshire White Horses page is devoted to the Tan Hill white horse itself, and Wikipedia independently describes the same figure from the same 1975 account.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
