    ('a3648096-b2ce-4f81-b704-59a1875012e1'::uuid, 'period_start', '-4500', NULL, 'fields-wd1-2026-09-26b-s007:a3648096-b2ce-4f81-b704-59a1875012e1:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-4500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0035)", "decision": "clear", "status": "MISSING", "reasoning": "Only Helston History gives a year (''c.1000 B.C.''); the Cornwall Guide gives ''around 3,500 years'' (not a readable date) and the Megalithic Portal only ''Neolithic and Bronze Age''. No two independent sources date the stone''s erection, and the stored -4500 is unsupported.", "value_page": null}]'::jsonb),
    ('a3648096-b2ce-4f81-b704-59a1875012e1'::uuid, 'site_type', 'Megalithic stones', 'Standing stone', 'fields-wd1-2026-09-26b-s007:a3648096-b2ce-4f81-b704-59a1875012e1:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Megalithic stones'' -> ''Standing stone''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=7294", "url": "https://www.megalithic.co.uk/article.php?sid=7294", "quote": "Type: Standing Stone (Menhir)", "outcome": "found"}, {"source": "http://www.helstonhistory.co.uk/old-customs/dry-tree-menhir/", "url": "http://www.helstonhistory.co.uk/old-customs/dry-tree-menhir/", "quote": "On the southern edge of the Goonhilly Station site is a `Standing Stone`, or MENHIR, c.1000 B.C., and a `Barrow`, to which there is an easily accessible footpath.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0035)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a single menhir; the Megalithic Portal and Helston History both call it a standing stone, which is more specific than the stored ''Megalithic stones''.", "value_page": null}]'::jsonb),
    ('a3648096-b2ce-4f81-b704-59a1875012e1'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Goonhilly_Downs', 'https://www.megalithic.co.uk/article.php?sid=7294', 'fields-wd1-2026-09-26b-s007:a3648096-b2ce-4f81-b704-59a1875012e1:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://en.wikipedia.org/wiki/Goonhilly_Downs'' -> ''https://www.megalithic.co.uk/article.php?sid=7294''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=7294", "url": "https://www.megalithic.co.uk/article.php?sid=7294", "quote": "Site Name: Dry Tree Menhir", "outcome": "found"}, {"source": "http://emcox.co.uk/the-dry-tree-menhir-goonhilly", "url": "http://emcox.co.uk/the-dry-tree-menhir-goonhilly", "quote": "The Dry Tree menhir is an igneous rock called gabbro, which is low in silica and rich in iron, magnesium, and calcium.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0035)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Goonhilly Downs article is about the nature reserve and plateau; the menhir has no Wikipedia article and its Historic England entry cannot be read by the checker, so the Megalithic Portal''s page on the Dry Tree Menhir is used; Emma Cox''s page names the same stone.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
