    ('a36bb548-bebc-4606-af26-9cded2b3cded'::uuid, 'period_start', '-5000', NULL, 'fields-wd1-2026-09-26b-s007:a36bb548-bebc-4606-af26-9cded2b3cded:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-5000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0127)", "decision": "clear", "status": "MISSING", "reasoning": "No excavation has dated the circles. A curator-archaeologist writing in Vreme says only assumptions remain that they are late Neolithic rondels, and the Vršac museum''s archaeologists reportedly think of Hunnic graves while others suggest the Middle Ages. The ''4500 BC'' and ''6500 years'' figures come from amateur associations. No securely attested start can be quoted.", "value_page": null}]'::jsonb),
    ('a36bb548-bebc-4606-af26-9cded2b3cded'::uuid, 'site_type', 'Geoglyphs', 'Earthwork', 'fields-wd1-2026-09-26b-s007:a36bb548-bebc-4606-af26-9cded2b3cded:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Geoglyphs'' -> ''Earthwork''', '[{"source": "https://vreme.com/en/kultura/tajna-iz-praistorije/", "url": "https://vreme.com/en/kultura/tajna-iz-praistorije/", "quote": "A third circular earthen structure was discovered near Vatin.", "outcome": "found"}, {"source": "https://globaljournals.org/GJHSS_Volume18/1-Possible-Gnomonic-Algorithm.pdf", "url": "https://globaljournals.org/GJHSS_Volume18/1-Possible-Gnomonic-Algorithm.pdf", "quote": "This unusual earthwork dated around five millennia ago can be seen in Figure 1.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0127)", "decision": "replace", "status": "MISSING", "reasoning": "Vreme''s curator-archaeologist calls the site a circular earthen structure, possibly a late Neolithic rondel. The Global Journals archaeoastronomy paper calls it an unusual earthwork. Kulturizam likewise describes concentric ditches and embankments 150 m across. No source calls it a geoglyph, so the specific type is Earthwork.", "value_page": null}]'::jsonb),
    ('a38c611d-9801-4b23-b965-fbe0f5d4af24'::uuid, 'geom', '0101000020E61000003742D028765BE03F27C1CB3AAD6B4840', 'SRID=4326;POINT(0.497389 48.839567)', 'fields-wd1-2026-09-26b-s007:a38c611d-9801-4b23-b965-fbe0f5d4af24:geom', 'fields-wd1-2026-09-26b-s007 (wd1-point): 48.841224050035, 0.5111647412432551 -> 48.839567, 0.497389', '[{"source": "https://www.wikidata.org/wiki/Q22963542", "url": "https://www.wikidata.org/wiki/Q22963542", "quote": "48°50''22.4\"N, 0°29''50.6\"E", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=6333557", "url": "https://www.megalithic.co.uk/article.php?sid=6333557", "quote": "Latitude: 48.839600N Longitude: 0.497300E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0053)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored point is the centre of La Ferté-Frênel, the seat of La Ferté-en-Ouche. The megalith there is the dolmen of the Pierre Couplée, just west of the village (the commune''s other megalith, the Glos-la-Ferrière menhir, lies some 6 km away). Wikidata and the Megalithic Portal both put the dolmen at about 48.8396 N, 0.4974 E, about 1.02 km from the stored point.", "value_page": null}]'::jsonb),
