    ('a3a38d98-16fc-464f-bbeb-c027813ef202'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26b-s007:a3a38d98-16fc-464f-bbeb-c027813ef202:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0124)", "decision": "clear", "status": "MISSING", "reasoning": "Gradina is a multi-layered site whose oldest layers are assigned only to the (Late) Bronze Age with no year; Wikipedia dates Celtic Scordisci presence in ''the area'' to the 3rd century BC and the Roman conquest of the fort to the 1st century BC, while Serbian heritage sources date the Roman fort''s material to the 1st-3rd centuries AD. No two sources date the site''s first occupation, so the field is emptied.", "value_page": null}]'::jsonb),
