    ('a3b55317-bae1-42b5-9c64-477749bdc2d5'::uuid, 'period_start', '-200', NULL, 'fields-wd1-2026-09-26b-s007:a3b55317-bae1-42b5-9c64-477749bdc2d5:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-200'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0108)", "decision": "clear", "status": "MISSING", "reasoning": "The only dating source, the MINCETUR record copied on turismoperuano.com, assigns the complex to the Early Intermediate Period through the Middle Horizon without a year (and elsewhere gives a garbled ''hacia 1600 DC.''); no two independent sources date its start, so the stored 200 BC cannot be kept.", "value_page": null}]'::jsonb),
    ('a3b55317-bae1-42b5-9c64-477749bdc2d5'::uuid, 'site_type', 'Necropolis/tombs complex', 'Cemetery', 'fields-wd1-2026-09-26b-s007:a3b55317-bae1-42b5-9c64-477749bdc2d5:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Necropolis/tombs complex'' -> ''Cemetery''', '[{"source": "https://en.wikipedia.org/wiki/Huamboy", "url": "https://en.wikipedia.org/wiki/Huamboy", "quote": "is an archaeological site featuring cemeteries and a village located on a hill of the same name in Peru", "outcome": "found"}, {"source": "https://www.turismoperuano.com/conjunto-arqueologico-huamboy-arequipa", "url": "https://www.turismoperuano.com/conjunto-arqueologico-huamboy-arequipa", "quote": "El Conjunto Arqueológico Huamboy, esta conformado por 5 Cementerios y una Aldea", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0108)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia and the MINCETUR record (turismoperuano.com) describe Huamboy as five cemeteries with looted burials plus a terraced village; neither calls it a necropolis or tombs, so the canonical type that the sources'' own word supports is Cemetery, not the stored Necropolis/tombs complex. The Wikidata ''mountain'' class is the hill it lies on.", "value_page": null}]'::jsonb),
    ('a42d9ff4-6d8d-4cb2-bb1d-64b1c66cb290'::uuid, 'site_type', 'Archaeological site', 'Sacred site', 'fields-wd1-2026-09-26b-s007:a42d9ff4-6d8d-4cb2-bb1d-64b1c66cb290:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Archaeological site'' -> ''Sacred site''', '[{"source": "https://coflein.gov.uk/en/sites/401097", "url": "https://coflein.gov.uk/en/sites/401097", "quote": "a sacred lake where quantities of prestige artefacts and weaponry were thrown by the Iron Age Celts as offerings to their gods", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=16615", "url": "https://www.megalithic.co.uk/article.php?sid=16615", "quote": "A Sacred Lake, into which many votive goods were offered from the late Iron Age (2nd century BC)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0154)", "decision": "replace", "status": "CONFLICT", "reasoning": "Coflein (RCAHMW) and the Megalithic Portal both describe Llyn Cerrig Bach as a sacred lake into which votive offerings were thrown, i.e. a sacred site, which is more specific than the generic Archaeological site.", "value_page": null}]'::jsonb),
    ('a44a209e-67dd-4d92-b976-d6f601d3b8e5'::uuid, 'site_type', 'Temple complex', 'Temple', 'fields-wd1-2026-09-26b-s007:a44a209e-67dd-4d92-b976-d6f601d3b8e5:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Temple complex'' -> ''Temple''', '[{"source": "https://en.wikipedia.org/wiki/Osorkon_III", "url": "https://en.wikipedia.org/wiki/Osorkon_III", "quote": "where she is depicted on the small temple Osiris-Heqa-djet in the", "outcome": "found"}, {"source": "https://travelwaysonline.blogspot.com/2009/12/temple-of-osiris-hek-djet-at-karnak-in.html", "url": "https://travelwaysonline.blogspot.com/2009/12/temple-of-osiris-hek-djet-at-karnak-in.html", "quote": "is a small temple dedicated to Osiris Hek-Djet (Heqadjet, \"Ruler of Eternity\").", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0022)", "decision": "replace", "status": "MISSING", "reasoning": "Both sources describe the Osiris Heqa-djet chapel as a single small temple with a gated courtyard, not a complex of temples, so Temple fits better than Temple complex.", "value_page": null}]'::jsonb),
    ('a44a209e-67dd-4d92-b976-d6f601d3b8e5'::uuid, 'source_url', 'https://www.archaeology.org/issues/304-1807/from-the-trenches/6698-trenches-egypt-luxor-karnak-osiris-chapel', 'https://digitalkarnak.ucsc.edu/Osiris-Heqa-Djet/', 'fields-wd1-2026-09-26b-s007:a44a209e-67dd-4d92-b976-d6f601d3b8e5:source_url', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''https://www.archaeology.org/issues/304-1807/from-the-trenches/6698-trenches-egypt-luxor-karnak-osiris-chapel'' -> ''https://digitalkarnak.ucsc.edu/Osiris-Heqa-Djet/''', '[{"source": "https://digitalkarnak.ucsc.edu/Osiris-Heqa-Djet/", "url": "https://digitalkarnak.ucsc.edu/Osiris-Heqa-Djet/", "quote": "The Osiris Heqa-Djet chapel is located in the northeastern area of the Amun precinct.", "outcome": "found"}, {"source": "https://travelwaysonline.blogspot.com/2009/12/temple-of-osiris-hek-djet-at-karnak-in.html", "url": "https://travelwaysonline.blogspot.com/2009/12/temple-of-osiris-hek-djet-at-karnak-in.html", "quote": "is a small temple dedicated to Osiris Hek-Djet (Heqadjet, \"Ruler of Eternity\").", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0022)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Archaeology Magazine article is about the Chapel of Osiris-Ptah Neb-ankh near the Tenth Pylon, not the chapel at this point; the site has no Wikipedia article of its own, and the Digital Karnak project page (UCLA/UC Santa Cruz) is about the Osiris Heqa-Djet chapel in the north-east of the Amun precinct.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('a45b9287-fe45-43b0-a8d6-8c434e16e65b'::uuid, 'period_name', '3000 - 1500 BC', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s007:a45b9287-fe45-43b0-a8d6-8c434e16e65b:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start -1000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1000) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('a45b9287-fe45-43b0-a8d6-8c434e16e65b'::uuid, 'period_start', '-2000', '-1000', 'fields-wd1-2026-09-26b-s007:a45b9287-fe45-43b0-a8d6-8c434e16e65b:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''-2000'' -> ''-1000''', '[{"source": "https://nesebar.net/articles/the-thracian-roots-of-mesembria-mlhjbmna", "url": "https://nesebar.net/articles/the-thracian-roots-of-mesembria-mlhjbmna", "quote": "Археологически разкопки са разкрили тракийски артефакти, датиращи от края на Бронзовата ера, около 1000 г. пр.н.е.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Nesebar", "url": "https://en.wikipedia.org/wiki/Nesebar", "quote": "Originally a Thracian settlement, known as Mesembria, the town became a Greek colony when settled by Dorians from Megara at the beginning of the 6th century BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0014)", "decision": "replace", "status": "MISSING", "reasoning": "Nesebar.net dates the earliest Thracian finds on the peninsula to the end of the Bronze Age, about 1000 BC, and Wikipedia has the Thracian settlement precede the Dorian colony of the early 6th century BC; the start lies in the 1500 - 500 BC bucket, not in the stored 3000 - 1500 BC one.", "value_page": null}]'::jsonb),
    ('a4a3242d-7110-406e-ba77-af035c6cf560'::uuid, 'period_name', '3000 - 1500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s007:a4a3242d-7110-406e-ba77-af035c6cf560:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start -500 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-500) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('a4a3242d-7110-406e-ba77-af035c6cf560'::uuid, 'period_start', '-3000', '-500', 'fields-wd1-2026-09-26b-s007:a4a3242d-7110-406e-ba77-af035c6cf560:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''-3000'' -> ''-500''', '[{"source": "https://journals.openedition.org/encyclopedieberbere/2511?lang=en", "url": "https://journals.openedition.org/encyclopedieberbere/2511?lang=en", "quote": "Le document datable le plus ancien qui ait été trouvé jusqu’à ce jour sur le site d’Hippone est un tesson attique du ve siècle av. J.-C.", "outcome": "found"}, {"source": "https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.04.0006:entry=hippo-regius", "url": "https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.04.0006:entry=hippo-regius", "quote": "The city that has been excavated lies in the plain between the vale of St. Augustine and the old coastline and was apparently not inhabited until 200 B.C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "MISSING", "reasoning": "G. Camps (Encyclopédie berbère) states that nothing is known of Hippo''s origins and that the oldest datable find on the site is a 5th-century BC Attic sherd; the Princeton Encyclopedia of Classical Sites says the excavated city was apparently not inhabited until 200 BC. The Phoenician 12th-century BC foundation is tradition without remains, so the securely attested start is the 5th century BC (-500), not the stored 3000 - 1500 BC bucket.", "value_page": null}]'::jsonb),
    ('a4a3242d-7110-406e-ba77-af035c6cf560'::uuid, 'site_type', 'Temple complex', 'City', 'fields-wd1-2026-09-26b-s007:a4a3242d-7110-406e-ba77-af035c6cf560:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Temple complex'' -> ''City''', '[{"source": "https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.04.0006:entry=hippo-regius", "url": "https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.04.0006:entry=hippo-regius", "quote": "The Roman and Early Christian city was excavated in part and at least some stages of its history revealed.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Hippo_Regius", "url": "https://en.wikipedia.org/wiki/Hippo_Regius", "quote": "A maritime city near the mouth of the Ubus", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Ruins of Hippo are the excavated remains of the ancient city of Hippo Regius (forum, theatre, baths, basilica, city blocks); the Princeton Encyclopedia and Wikipedia both describe it as a city, not a temple complex.", "value_page": null}]'::jsonb),
    ('a4ac2a6f-0159-447e-a6d2-7300fbc986ef'::uuid, 'site_type', 'Megalithic structures', 'Cave', 'fields-wd1-2026-09-26b-s007:a4ac2a6f-0159-447e-a6d2-7300fbc986ef:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Megalithic structures'' -> ''Cave''', '[{"source": "https://en.wikipedia.org/wiki/Sidr%C3%B3n_Cave", "url": "https://en.wikipedia.org/wiki/Sidr%C3%B3n_Cave", "quote": "The Sidrón Cave (Asturian: Cueva del Sidrón) is a non-carboniferous limestone karst cave system located in the Piloña municipality of Asturias, northwestern Spain, where Paleolithic rock art and the fossils of more than a dozen Neanderthals were found.", "outcome": "found"}, {"source": "https://info.igme.es/ielig/LIGInfo.aspx?Codigo=CA011", "url": "https://info.igme.es/ielig/LIGInfo.aspx?Codigo=CA011", "quote": "El principal valor de la cueva de El Sidrón es el importante yacimiento paleoantropológico y arqueológico que contiene en sus depósitos interiores.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0133)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Spanish Geological Survey''s inventory describe the site as a karst cave whose inner deposits hold a Neanderthal fossil site; there are no megalithic structures, so Cave replaces Megalithic structures.", "value_page": null}]'::jsonb),
    ('a4b56463-b8e7-48af-80d0-c01b5c9caba9'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd1-2026-09-26b-s007:a4b56463-b8e7-48af-80d0-c01b5c9caba9:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('a4b56463-b8e7-48af-80d0-c01b5c9caba9'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26b-s007:a4b56463-b8e7-48af-80d0-c01b5c9caba9:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "clear", "status": "MISSING", "reasoning": "Kiesling and the Wikipedia sentence derived from him only say the walled settlement is of the ''Persian and Hellenistic period'' and was abandoned at the end of the 1st century BC; no source states when it began, and the separate Urartian-period and Bronze Age graves near the village are other components, so no start can be dated by two independent sources.", "value_page": null}]'::jsonb),
    ('a4bfb021-8b30-4a2c-8d13-ed70b474ab0f'::uuid, 'site_type', 'City/town/settlement', 'Fort', 'fields-wd1-2026-09-26b-s007:a4bfb021-8b30-4a2c-8d13-ed70b474ab0f:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''City/town/settlement'' -> ''Fort''', '[{"source": "https://www.encyclopediaofukraine.com/display.asp?linkpath=pages%5CN%5CE%5CNemyrivfortifiedsettlement.htm", "url": "https://www.encyclopediaofukraine.com/display.asp?linkpath=pages%5CN%5CE%5CNemyrivfortifiedsettlement.htm", "quote": "An early Scythian (7th–6th century BC) fortified settlement on both banks of a tributary of the Boh River near Sazhky, Nemyriv raion, Vinnytsia oblast. Excavations from 1909 to 1948 identified the remains of defensive earthen walls and trenches.", "outcome": "found"}, {"source": "https://uk.wikipedia.org/wiki/%D0%9D%D0%B5%D0%BC%D0%B8%D1%80%D1%96%D0%B2%D1%81%D1%8C%D0%BA%D0%B5_%D0%B3%D0%BE%D1%80%D0%BE%D0%B4%D0%B8%D1%89%D0%B5", "url": "https://uk.wikipedia.org/wiki/%D0%9D%D0%B5%D0%BC%D0%B8%D1%80%D1%96%D0%B2%D1%81%D1%8C%D0%BA%D0%B5_%D0%B3%D0%BE%D1%80%D0%BE%D0%B4%D0%B8%D1%89%D0%B5", "quote": "Городище займає площу понад 100 га. Обнесені ровом і земляним валом 9 га були безпосереднім місцем містечка.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0151)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Encyclopedia of Ukraine calls the site a fortified settlement with defensive earthen walls and trenches, and Ukrainian Wikipedia (type: gorodyshche, hillfort) describes a hillfort of over 100 ha whose 9 ha town core was enclosed by a ditch and earth rampart, so it is a fortified hillfort rather than an open city, town or settlement.", "value_page": null}]'::jsonb),
    ('a50cf939-77f1-489c-82f7-93b07b2bc5ae'::uuid, 'site_type', 'Megalithic structures', 'Standing stone', 'fields-wd1-2026-09-26b-s007:a50cf939-77f1-489c-82f7-93b07b2bc5ae:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Megalithic structures'' -> ''Standing stone''', '[{"source": "https://en.wikipedia.org/wiki/Obelisk_of_Axum", "url": "https://en.wikipedia.org/wiki/Obelisk_of_Axum", "quote": "The steles were probably carved and erected during the 4th century CE by subjects of the Kingdom of Aksum, an ancient Ethiopian civilization.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Obelisk_of_Axum", "url": "https://en.wikipedia.org/wiki/Obelisk_of_Axum", "quote": "Single, solid block of a weather-resistant stone similar to granite", "outcome": "found"}, {"source": "https://madainproject.com/obelisk_of_aksum", "url": "https://madainproject.com/obelisk_of_aksum", "quote": "is a monumental stele dating to the 4th century CE, located in the historic city of Axum", "outcome": "found"}, {"source": "https://madainproject.com/obelisk_of_aksum", "url": "https://madainproject.com/obelisk_of_aksum", "quote": "It stands approximately 24 metres (79 feet) in height and is hewn from a single block of phonolite", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0050)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the Obelisk of Axum as a single erected monolithic stele (a carved funerary marker 24 m high), i.e. one standing stone, not a group of megalithic structures; Standing stone is the most specific canonical type for an upright monolith.", "value_page": null}]'::jsonb),
    ('a511e195-58d5-40e8-af84-baa83518f5e8'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd1-2026-09-26b-s007:a511e195-58d5-40e8-af84-baa83518f5e8:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('a511e195-58d5-40e8-af84-baa83518f5e8'::uuid, 'period_start', '-300', NULL, 'fields-wd1-2026-09-26b-s007:a511e195-58d5-40e8-af84-baa83518f5e8:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-clear): ''-300'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0142)", "decision": "clear", "status": "MISSING", "reasoning": "The Princeton Encyclopedia of Classical Sites, the Ministry of Culture page and Kulturenvanteri only name Hellenistic, Roman and Byzantine remains, an inscription honouring Trajan and Imperial coinage; no source gives a year or century for the city''s foundation or first occupation, so the stored 300 BC cannot be confirmed and the field is emptied.", "value_page": null}]'::jsonb),
    ('a57d3d87-6660-4136-a523-434165373169'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s007:a57d3d87-6660-4136-a523-434165373169:period_name', 'fields-wd1-2026-09-26b-s007 (wd1-derive-period-name): period_start -1000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1000) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('a57d3d87-6660-4136-a523-434165373169'::uuid, 'period_start', '-500', '-1000', 'fields-wd1-2026-09-26b-s007:a57d3d87-6660-4136-a523-434165373169:period_start', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''-500'' -> ''-1000''', '[{"source": "https://www.baslermuenster.ch/zeitgeschichte/kelten-und-roemer", "url": "https://www.baslermuenster.ch/zeitgeschichte/kelten-und-roemer", "quote": "Bereits in der Spätbronzezeit, um 1000 v.Chr. wurde auf dem gegen Rhein und Birsig steilabfallenden Münsterhügel eine befestigte Höhensiedlung angelegt.", "outcome": "found"}, {"source": "https://www.bs.ch/pd/kultur/museen-und-andere-dienststellen/archaeologie/vermittlung/infostellen/bronzezeitlicher-graben", "url": "https://www.bs.ch/pd/kultur/museen-und-andere-dienststellen/archaeologie/vermittlung/infostellen/bronzezeitlicher-graben", "quote": "Spätbronzezeitliche Siedlung auf dem Münsterhügel, um 900 v. Chr.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0138)", "decision": "replace", "status": "MISSING", "reasoning": "The hill''s first occupation is a fortified Late Bronze Age hilltop settlement: the Minster''s history page dates its foundation to c. 1000 BC, and the cantonal archaeology service shows the Late Bronze Age settlement and ditch on the Münsterhügel c. 900 BC. The later Celtic oppidum (c. 80-50 BC) is a second phase, so the start falls in 1500-500 BC, not the stored bucket.", "value_page": null}]'::jsonb),
    ('a57d3d87-6660-4136-a523-434165373169'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26b-s007:a57d3d87-6660-4136-a523-434165373169:site_type', 'fields-wd1-2026-09-26b-s007 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://en.wikipedia.org/wiki/Basel-M%C3%BCnsterh%C3%BCgel", "url": "https://en.wikipedia.org/wiki/Basel-M%C3%BCnsterh%C3%BCgel", "quote": "The fort was abandoned or destroyed shortly after its construction", "outcome": "found"}, {"source": "https://www.baslermuenster.ch/zeitgeschichte/kelten-und-roemer", "url": "https://www.baslermuenster.ch/zeitgeschichte/kelten-und-roemer", "quote": "Deshalb liess Kaiser Tiberius um 17 n.Chr. ein Kastell errichten, das etwa den Dimensionen seines Vorgängers folgte.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0138)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site''s Wikipedia article describes the Münsterhügel as a late La Tène fort (oppidum) later rebuilt as a Roman castrum, and the Minster''s history page records the Roman Kastell (fort) built on the hill c. AD 17; Fort is the specific type both support, whereas neither calls it a fortress or citadel.", "value_page": null}]'::jsonb),
